var JINGWEN = window.JINGWEN || (window.JINGWEN = {});
JINGWEN['s23'] = {"id":"s23","title":"性命圭旨","subtitle":"尹真人·元亨利三集","sections":[{"h":"元集·大道說","paras":[{"t":"庖羲上聖，畫八卦以示人，使萬世之下，知有養生之道。","py":[]},{"t":"廣成子謂黃帝曰：至陰肅肅，至陽赫赫。赫赫發乎地，肅肅出乎天。我為汝遂於大明之上矣，至彼至陽之原也；為汝入於穹冥之門矣，至彼至陰之原也。","py":[]},{"t":"軒轅再拜曰：廣成子之謂天矣。","py":[]},{"t":"周公繇易曰：君子終日乾乾。","py":[]},{"t":"孔子翼曰：終日乾乾，反復道也。","py":[]},{"t":"夫道也者，位天地、育萬物，曰道；揭日月、生五行，曰道；多於恆河沙數，曰道；孤則獨無一侶，曰道；直入鴻蒙而還歸溟涬，曰道；善集造化而頓超聖凡，曰道；目下機境未兆而突而靈通，曰道；眼前生殺分明而無能逃避，曰道；處卑污而大尊貴，曰道；居幽暗而極高明，曰道；細入剎塵，曰道；大包天地，曰道：從無入有，曰道；作佛成仙，曰道。佛經五千四十八卷，也說不到了處；中庸三十三章，也說不到窮處；道德五千餘言，也說不到極處。道也者，果何謂也？一言以定之，曰炁也。","py":[]},{"t":"原夫一炁蟠集，溟溟涬涬，窅窅莫測，氤氳活動，含靈至妙，是為太乙，是為未始之始。始也，是為道也，故曰無始。","py":[]},{"t":"夫天地之有始也，一炁動盪，虛無開合，雌雄感召，黑白交凝，有無相射，混混沌沌，沖虛至聖，包元含靈，神明變化，恍惚立極，是為太易，是為有始之始。始也，是謂道生一也，是曰元始。","py":[]},{"t":"夫天地之太極也，一炁斯析，真宰自判，交映羅列，萬靈肅護，陰陽判分，是為太極，是謂一生二也，是曰虛皇。","py":[]},{"t":"陰陽既判，天地位焉，人乃育焉，是謂二生三也，是曰混元。","py":[]},{"t":"陽之清者，升上而煥麗也，則日月星辰布焉。故天左運，三光右旋。陽之清者，騰上而會於陽也，故風雲動而雷雨作焉。陰之濁者，重滯而就地也，則海嶽奠峙而五穀草木昌焉。故巖岫出雲，山澤通氣。陰陽之氣閉而不通也，則雪霜結而凍冰焉。陰之濁者，積冱而下凝也，穴巖幽藏而深邃，故五穀八石以錯雜焉。天地之中，陰陽正氣之所交也，聖人焉，仙佛焉，庶民焉，賢愚壽夭，寔所宰焉。胎卵濕化，無有息焉。是為六合也，是謂三生萬物也。","py":[]},{"t":"人稟氤氳之氣而生，而長至於二八之年。則九三之陽乃純。當是時也，豈非上德之大人乎？忽天一朝，謀報渾敦之德者至，乃日鑿一竅，則九三之陽，蹄驟奔蹶，而去之六六之中矣。由是乾不能純，而破於離；坤有所含，而實於坎。","py":[]},{"t":"若夫至聖神人，能知道體太極之所以判，能知死生根本之所以始，能知乾坤陰陽之所以乘，能知天玄地牡之所以交，是以法乾坤之體，效坎離之用，握陰陽之柄，過生死之關，取坎中之陽，填離中之陰，離陰既實，則複純白為乾矣。","py":[]},{"t":"斯時補足乾元，複全渾敦，以全親之所生，以全天之所賦，是為囫囫圇圇一個完人也。再加向上功夫，精進不怠，則金丹成而聖胎圓，聖胎圓而真人現。真人出現，變化無窮，隱顯莫測，而與鐘、呂、王、馬並駕，亦又何難？","py":[]},{"t":"奈何世人不明此道，盛不知養，衰不知救，日復一日，陽盡陰純，死而為鬼。故紫陽真人曰：嗟夫！人身難得，光陰易遷，罔測脩短，安逃業報？不自及早省悟，唯只甘分待終。若臨期一念有差，立墮三塗惡趣，則動經塵劫，無有出期。當此之時，雖悔何及？","py":[]},{"t":"故三教聖人，以性命學開方便門，教人燻修，以脫生死。","py":[]},{"t":"儒家之教，教人順性命以還造化，其道公。","py":[]},{"t":"禪宗之教，教人幻性命以超大覺，其義高。","py":[]},{"t":"老氏之教，教人修性命而得長生，其旨切。","py":[]},{"t":"教雖分三，其道一也。","py":[]},{"t":"儒之聖教曰：安汝止，欽厥止，艮其止，止其所，緝熙敬止，在止至善。黃中通理，正位居體，思不出位，立不易方，居天下之廣居，立天下之正位，行天下之大道。渾然在中，粹然至善。誠盡處腔子，裏樂處方寸。神明之舍，道義之門，活潑潑地，樂在其中。肫肫其仁，淵淵其淵，浩浩其天，天下歸仁，退藏於密，何思何慮之天，不識不知之地。難以悉紀，要而言之，無非為此性命之道也。","py":[]},{"t":"道之玄教曰：玄牝之門，天地之根，生身處，復命關，金丹之母，玄關之竅，凝結之所，呼吸之根。甲乙壇，戊己戶，心源性海，靈府靈臺蓬萊島。硃砂鼎、偃月爐、神室，氣穴、土釜、穀神、靈根、把柄、坎離交媾之鄉，千變萬化之祖，生死不相關之地，鬼神覷不破之機。難以悉紀，要而言之，無非為此性命之道也。","py":[]},{"t":"釋之禪教曰：不二法門、甚深法界、虛空藏、寂滅海、真實地、總持門。彼岸、淨土、真境心地、極樂國。如來藏、舍利子、菩薩地、光明藏、圓覺海、般若岸、法王城、西方、天堂、空中、真際、這個、三摩地、華藏海，陀羅尼門、不動道場、波羅蜜地，難以悉紀。要而言之，無非為此性命之道也。","py":[]},{"t":"儒曰：存心養性。道曰：修心煉性。釋曰：明心見性。心性者，本體也。","py":[]},{"t":"儒之執中者，執此本體之中也。道之守中者，守此本體之中也。釋之空中者，本體之中本洞然而空也。","py":[]},{"t":"道之得一者，得此本體之一也。釋之歸一者，歸此本體之一也。儒之一貫者，以此本體之一而貫之也。","py":[]},{"t":"餘於是而知：不執中、不一貫，其能聖而孔子乎？不守中，不得一，其能玄而老子乎？不空中、不歸一，其能禪而釋迦乎？唯此本體。以其虛空無朕，強名曰中；以其霹出端倪，強名曰一。然而中即一之藏也，一即中之用也。","py":[]},{"t":"故天得此而天天，地得此而地地，人得此而人人。而天地人之大道，原於此也。","py":[]},{"t":"皇得此而皇皇，帝得此而帝帝，王得此而王王。而皇帝王之大道，原於此也。","py":[]},{"t":"聖得此而聖聖，玄得此而玄玄，禪得此而禪禪。而聖玄禪之大道，原於此也。","py":[]},{"t":"帝皇之得道者，若羲、農、黃帝焉。仕隱而得道者，若老、莊、關令焉。侯王而得道者，若子房、淮南焉。山巖而得道者，若鐘、呂、希夷焉。","py":[]},{"t":"道之在天地間，成仙作佛者，歷歷不可以指數也。伏睹總仙之傳，始知自古以來沖舉者十萬餘人，拔宅者八千餘處。奇若子晉之驂鸞、琴高之控鯉，壽若李脫之八百、安期之三千。或住世而留形，或厭世而屍解。復有道成而隱，但為身謀，不肯遺名於世間者、豈勝道哉？是以深山妙窟，代不乏人，或隱或顯，寧具知乎？","py":[]},{"t":"古之王公大人，折節下士，只為有道存爾。周子曰：天地間，至尊者道，至貴者德，至難得者人。人而至難得者，道德有於身而已矣。","py":[]},{"t":"先哲雲：人身難得今已得，大道難明今已明。此身不向今生度，更向何生度此身？","py":[]},{"t":"世人不明此身虛幻，是四大假合之物耳。速如水上之漚，瞬若石中之火。人壽雖曰百年，迨其七十，固亦稀矣。","py":[]},{"t":"今以有限易摧之身，日逐無涯不測之事。一息不來，倏然長往，命未告終，真靈已投於別殼矣。當斯之時，雖榮居極品，祿享千鐘，家豐無價之珠，室富傾城之美，悉皆拋下，非已有也。所有與於偕行者，平昔所作罪業而已。故云：萬般將不去，惟有業隨身。","py":[]},{"t":"回光集雲：千年鐵樹花開易，一失人身再復難。","py":[]},{"t":"悟真篇雲：試問堆金等山嶽，無常買得不來麼？","py":[]},{"t":"呂純陽雲：萬劫千生得個人，須知先世種來因。速覺悟，出迷津，莫使輪回受苦辛。","py":[]},{"t":"張紫陽雲：休教燭被風吹滅，六道輪回莫怨天。","py":[]},{"t":"三復斯語，能不憮然失乎？","py":[]},{"t":"夫人慾免輪回，而不墮於世綱者，莫若修煉金丹，為昇天之靈梯，超凡之徑路也。其道至簡至易，雖愚昧小人得而行之，亦立躋聖域。奈何世之修真者，志道而不專精，專精而不勤久，是以學者眾而成者寡也。","py":[]},{"t":"尚書曰：知之非艱，行之惟艱。","py":[]},{"t":"道經曰：上士聞道，勤而行之。聞而不行，道安能成？","py":[]},{"t":"陳泥丸曰：我昔修行得真訣，晝夜功夫無斷絕。一朝行滿人不知，四面皆成夜光闕。","py":[]},{"t":"馬丹陽曰：師恩深重終難報，誓死環牆煉至真。","py":[]},{"t":"二公念生死事大，無常迅速，發勇猛心，辨精進力，若不立此大志，安能脫樊籠，而超霄漢者哉？","py":[]},{"t":"呂祖有云：辛勤二三年，快活千萬劫。","py":[]},{"t":"蓋天有時而傾，地有時而陷，山有時而摧，海有時而竭。唯道成之後，乘飛龍，駕紫霧，翱翔天外，逍遙太虛，數不得而限之，命不得而拘之，真常本體，無有盡時，回顧世間之樂，何樂如之？","py":[]},{"t":"嘗稽道德經曰：雖珙壁以先駟馬，不如坐進此道。此予道說之所由作也。","py":[]}]},{"h":"元集·性命說","paras":[{"t":"夫學之大，莫大於性命。性命之說，不明於世之久矣。","py":[]},{"t":"何謂之性？元始真如，一靈炯炯是也。","py":[]},{"t":"何謂之命？先天至精，一炁氤氳是也。","py":[]},{"t":"然有性，便有命；有命，便有性。性命原不可分。但以其在天，則謂之命；在人，則謂之性。性命實非有兩。況性無命不立，命無性不存，而性命之理，又渾然合一者哉。","py":[]},{"t":"故易曰：乾道變化，各正性命。中庸曰：天命之謂性。此之謂也。","py":[]},{"t":"乃玄門專以氣為命，以修命為宗，以水府求玄立教。故詳言命而略言性，是不知性也，究亦不知命。","py":[]},{"t":"禪家專以神為性，以修性為宗，以離宮修定立教。故詳言性而略言命，是不知命也，究亦不知性。","py":[]},{"t":"豈知性命本不相離，道釋原無二致。神氣雖有二用，性命則當雙修也哉。","py":[]},{"t":"賢人之學，存心以養性，修身以立命。聖人之學，盡性而至命。","py":[]},{"t":"謂性者神之始，神本於性，而性則未始神，神所由以靈。命者氣之始，氣本於命，而命則未始氣，氣所由以生。","py":[]},{"t":"身中之精，寂然不動。蓋剛健中正，純粹精者存，乃性之所寄也，為命之根矣。","py":[]},{"t":"心中之神，感而遂通。蓋喜、怒、哀、懼、愛、惡欲者存，乃命之所寄也，為性之樞矣。","py":[]},{"t":"性而心也，而一神之中炯。命而身也，而一氣之周流。故身心，精神之舍也。而精神，性命之根也。","py":[]},{"t":"性之造化，系乎心。命之造化，系乎身。見解知識，出於心哉。思慮念想，心役性也。舉動應酬，出於身哉。語默視聽，身累命也。","py":[]},{"t":"命有身累，則有生死。性受心役，則有去來。有生死，不能至命也。有去來，不能盡性也。","py":[]},{"t":"故盈天地間，皆是生氣，參贊兩間，化育萬物。其命之流行，而不息者乎？蓋生之理，具於命也。盈天地間，皆是靈覺，明光上下，照臨日月。未始性，而能性我之性者，性之始也。未始命，而能命我之命者，命之始也。","py":[]},{"t":"天竅圓而藏性，地竅方而藏命。稟虛靈以成性，中天地以立命。性成命立，其中有神。命蒂元氣，性根元神。潛神於心，聚氣於身。其中有道。","py":[]},{"t":"性有氣質之性，有天賦之性；命有分定之命，有形氣之命。","py":[]},{"t":"君子修天賦之性，克氣質之性；修形氣之命，付分定之命。分言之，則二；合言之，則一。其中有理。","py":[]},{"t":"是以神不離氣，氣不離神，吾身之神氣合，而後吾身之性命見矣。性不離命，命不離性，吾身之性命合，而後吾身未始性之性、未始命之命見矣。未始性之性、未始命之命，是吾之真性命也。我之真性命，即天地之真性命，亦即虛空之真性命也。","py":[]},{"t":"故聖賢持戒定慧而虛其心，煉精氣神而保其身。身保則命基永固，心虛則性體常明。性常明則無來無去，命永固則何死何生。況死而去者，僅僅形骸耳。而我之真性命，則通晝夜、配天地，徹古今者，何嘗少有泯滅也哉。","py":[]},{"t":"嘗觀之草木焉，歸根復命，而性在其中矣。性而神也，則花。花而實也，而命又在其中矣。自形中之神，以入神中之性，此之謂歸根復命。","py":[]},{"t":"又嘗譬之男女媾精焉，而一點之善，落於子宮者，氣合之而為命也，而性即存於其間。其即一陰一陽之相搏，而一點落於黃中之中以成性。乃妙合而凝，不測之神乎？此之謂性命妙合。","py":[]},{"t":"奈妙合之道不明，修世者遺命，且並率性之竅妙，不得而知之，矧能煉之乎？非流於狂蕩，則失於空寂，不知其命，末後何歸。修命者遺性，且並造命之功夫，不得而知之，知能守之乎？","py":[]},{"t":"非執於有作，則失於無為。不知其性，劫運何逃？即二氏之初，亦豈如是乎？","py":[]},{"t":"吾聞釋迦生於西方，亦得金丹之道，是性命兼修，為最上乘法，號曰金仙。","py":[]},{"t":"呂祖亦曰：只知性，不知命，此是修行第一病。只修祖性不修丹，萬劫陰靈難入聖。","py":[]},{"t":"豈但如今之導引者流，而以形骸為性命焉已哉。又豈但如今煉神煉氣者流，而以神氣為性命焉己哉。又豈但如今修性修命者流，而以性命為性命焉己哉。是皆不唯無益於性命，而且有害於性命。不得性命之真，良可歎也。","py":[]},{"t":"故嘗論之，人在母腹，呼吸相會，是以母之性命為性命，而非自為性命。至於出胞斷蒂，而後自為性命，然亦非真常之性命也。必於自為性命中，而養成乾元面目，露出一點真靈。","py":[]},{"t":"形依性，形不壞；神依性，神不滅。知性而盡性，盡性而至命。乃所謂虛空本體，無有盡時。天地有壞，這個不壞，而能重立性命，再造乾坤者也。","py":[]},{"t":"故道家不知此，則謂之旁門；釋氏不知此，則謂之外道，又焉能合天地之德，而與太虛同體哉？噫！至此而性命之說，無餘旨矣。","py":[]}]},{"h":"元集·死生說","paras":[{"t":"大眾好生惡死，以莫識死生故。生從何來，死從何去。徒在生前，奔馳謀作，致大虧生道，不得逍遙。故於死後，渺茫淪落，不戡破死門，竟墮輪轉。","py":[]},{"t":"所以仙佛出世，汲汲以一大事因緣，使人知去來處，徐徐引出生死苦海。易系曰：原始要終。故知死生之說，蓋無始之始，強名乾元，即本來妙覺；無終之終，強名道岸，即無餘涅槃。","py":[]},{"t":"生而生也，而其所以生者，固在於此；至死而死也，而其所以不死者，亦在於此。此而不知，則未有不隨生而存，隨死而亡者，沉溺惡道，出沒無期。","py":[]},{"t":"生則是第八識神阿賴耶主之，死亦是第八識神阿賴耶主之。投胎則此識先來，捨身則此識後去。故曰：去後來先作主公。經頌曰：善業從下冷，惡業從上冷，二皆至於心，一處同時舍。當此之際，如生龜解殼，活蟹落湯，地水火風，各自分散。","py":[]},{"t":"而神既離形，但看世界，與潑墨相似，東西莫辨，上下不知。只見有緣之處，一點妄明。見明色，發明見，想成流，愛為種。納想為胎，入母中官，稟氣受質。氣則頓具四大，漸成諸根，心則頓具四蘊，漸成諸識。","py":[]},{"t":"十月胎完，及期而育，地覆天翻，人驚胞破，如行山巔蹶什之狀。頭懸足撐而出。囫圇一聲，天命真元，著於祖竅。晝居二目，而藏於泥丸；夜潛兩腎，而蓄於丹鼎。乳以養其五臟，炁則沖乎六腑。骨弱如綿，肉滑如飴，精之至也；視而不瞬，哮而不嘎，和之至也。此乃赤於混沌，純靜無知，屬陰䷁坤卦。","py":[]},{"t":"自一歲至三歲，長元炁六十四銖，一陽生乎䷗複卦。","py":[]},{"t":"至五歲，又長元炁六十四銖，二陽生乎䷒臨卦。","py":[]},{"t":"至八歲，又長元炁六十四銖，三陽生乎䷊泰卦。","py":[]},{"t":"至十歲，又長元炁六十四銖，四陽生乎䷡大壯。","py":[]},{"t":"至十三歲，又長元炁六十四銖，五陽生乎䷪夬卦。","py":[]},{"t":"至十六歲，又長元炁六十四銖，六陽是為乾䷀卦。","py":[]},{"t":"盜天地三百六十銖之正炁，原父母二十四銖之祖炁，共得三百八十四銖，以全周天之造化，而為一斤之數也。","py":[]},{"t":"此時，純陽既備，微陰未萌，精炁充實，如得師指，修煉性命，立可成功矣。","py":[]},{"t":"自此以後，欲情一動，元炁即泄，不知禁懇，貪戀無已。故由十六至二十四歲，耗元炁六十四銖，應乎䷫姤卦。一陰初生，品物鹹章，淳澆樸散，去本雖未遠，愎霜之戒，己見於初，又若勤修煉，可謂不遠複者矣。","py":[]},{"t":"至三十二歲，耗元炁六十四銖，應乎䷠遯卦。二陰浸長，陽德漸消，欲慮蜂起，真源流蕩，然而血氣方剛，志力果敢，若勤修煉，則建立丹基，亦易為力。","py":[]},{"t":"至四十歲，又耗元炁六十四銖，應乎䷋否卦。天地不交，二氣各複其所，陰用事於內，陽失位於外，若勤修煉，則危者可安，亡者可保。","py":[]},{"t":"至四十八歲，又耗元炁六十四銖，應乎䷓觀卦。二陽在外，而陽德微，重陰上行，而陰氣盛，若勤修煉，則可抑方盛之陰柔，扶向微之陽德。","py":[]},{"t":"至五十六歲，又耗元炁六十四銖，應乎䷖剝卦。五陰並升乎上，一陽將反乎下，陰氣橫潰，陽力僅存，若勤修煉，如續火於將窮之木，布雨於垂槁之苗。","py":[]},{"t":"至六十四歲，卦氣已周，所得天地父母之元炁三百八十四銖、而為一斤之數者，耗散已盡，復返於坤䷁。純陰用事，陽氣未萌，若勤修煉，時時採藥，時時栽接，則陰極而能生陽，窮上而能反下，革柔為剛，還老為強矣。","py":[]},{"t":"於此時不遇至人，汲汲修煉，雖保餘年，皆籍穀精以培後天之精氣，無複有先天之元炁矣，安能長生不死哉？","py":[]},{"t":"此所以虛化神、神化氣、氣化血、血化形、形化嬰、嬰化童、童化少、少化壯、壯化老、老化死、死複化為虛、虛複化為神、神複化為氣、氣複化為物，化化不間，猶環之無窮。","py":[]},{"t":"夫方物非欲生，不得不生，萬物非欲死，不得不死。任他塵生塵滅，萬化萬生，不能脫離苦海，劫劫生生，輪回不絕，無終無始，如汲井輪。三界凡夫，無一不遭此沉溺。","py":[]},{"t":"故世人莫知生從何來，蓋參父母未生前；死從何來，知來然後知生處。世人莫問死從何去，蓋參魂遊魄降後；生從何去，知去然後知死處。死之機由於生，生之機原於死。無死機不死，無生機不生。生死之機兩相關，世人所以有生死，生死之機不相關，至人所以超生死。有生死者，身也；無生死者，心也。敦複則心生迷，迷複則心死。","py":[]},{"t":"故仙佛湣之，說一切眾生，具有本來一靈真覺，但昏惑不見，使天命之性，浪化遷流，轉轉不悟。而世世墮落，失身於異類，透靈於別殼，至真性根，不復於人。","py":[]},{"t":"我當以聖道，令眾生永離妄想，能致自身如仙家之長生、佛氏之不死雲。","py":[]}]},{"h":"元集·邪正說","paras":[{"t":"大道生天、生地，天地生人、生物。天、地、人、物一性同體。天有陰陽，地有剛柔，物有牝牡，人有男女。","py":[]},{"t":"有陰陽斯有日月星辰，有剛柔斯有山川草木，有牝牡斯有胎卵濕化，有男女斯有配偶生育。","py":[]},{"t":"眾生因配偶有淫慾，因生育有恩愛。有淫慾、恩愛，故有魔障、煩惱。有魔障、煩惱，故有一切苦厄。有一切苦厄，故有生老病死。","py":[]},{"t":"是乙太上蘊好生之德，開度世之門，著經立法，教人返樸還淳。無欲觀妙，有欲觀竅。致虛守靜，歸根復命。早複重積，深根妙蒂。得一守中，虛心實腹。弱志強骨，挫銳解紛，和光同塵。專氣致柔，抱一無離。知雄守雌，知白守黑。閉門塞兌，被褐懷玉。窅窅冥冥，其精曰生，恍恍惚惚，其精不泄。日生則日長，不泄則不竭。精能化氣，氣能化神，神能還虛。五行不能盜，陰陽不能制。與道為體，超出天地。此乃老子清靜無名之道也。","py":[]},{"t":"至漢魏伯陽真人禮金碧經而作參同契，始有龍鉛虎汞之名。愛及唐宋，諸仙疊出，丹經燦然。橫說豎說，種種異名，載於丹書，不可勝數。究竟本來，無非吐露同出異名之一物耳。","py":[]},{"t":"蓋聖師闡教，敷楊備細詳說，實欲人人領悟、個個成真，殊不知名愈深而事愈繁，書愈多而道愈晦。況多為庚辭隱語，孔竅其門，使學者無罅縫可入，往往目眩心搖，望溟之歎。","py":[]},{"t":"幸吾師尹真人出，欲續大道之一絲，以複無名之古教。於是剪除繁羌，撮其樞要，掃除譬喻，獨露真詮，標摘正理，按圖立象，不可施於筆者，筆之不可發於語者。語之直指何者是鉛汞，何者是龍虎，何者是鼎爐，何者是藥物，何者謂之採取，何者謂之抽添，何者謂之溫養，何者謂之火候，何者是真種子，何者是真性命，何者是結胎，何者是了當，歷歷發明，毫髮無隱。後之有志於道者，再不為丹經所惑也。","py":[]},{"t":"況丹經子書，汗牛充棟，講理者多，留訣者少。初無下手入門，次無採藥結胎，末無極則歸著。後人不識次序，如何湊泊得來？不免有攙前越後之差，首顛尾倒之亂。學道一生，不得其門而入者多矣。間有入門者而不知升階，有升階者而不知登堂，有登堂者而不知入室。是以次第工夫乃修真之首務，豈可缺焉？","py":[]},{"t":"予最愛藏經中四句偈曰：眾生無邊誓願度，煩惱無邊誓願斷，法門無量誓願學，佛道無上誓願成。世尊亦曰：度盡眾生，然後作佛。區區由是，發一念慈悲，罄將師投祕訣徹底掀番，滿盤托出，籲徠後之有緣，複返天界而不沉溺於苦海中者。此予之心也。","py":[]},{"t":"其一曰：涵養本原，救護命寶。","py":[]},{"t":"其二曰：安神祖竅，翕聚先天。","py":[]},{"t":"其三曰：蟄藏氣穴，眾妙歸根。","py":[]},{"t":"其四曰：天人合發，採藥歸壺。","py":[]},{"t":"其五曰：乾坤交媾，去礦留金。","py":[]},{"t":"其六曰：靈丹入鼎，長養聖胎。","py":[]},{"t":"其七曰：嬰兒現形，出離苦海。","py":[]},{"t":"其八曰：移神內院，端拱冥心。","py":[]},{"t":"其九曰：本體虛空，超出三界。","py":[]},{"t":"於中更有煉形、結胎、火候等諸心法，以全九轉還丹之功。","py":[]},{"t":"大道口訣，至此吐露盡矣。今之道者，峨冠方袍，自足自滿，不肯低情下意，求師指授大道次第，惟只以盲弓盲，趨入旁蹊曲徑。豈知道法三千六百、大丹二十四品皆是傍門，獨此金丹一道是條修行正路。除此以外，再無別途可以成仙作佛也。","py":[]},{"t":"故法華會上，世尊指曰：唯此一事實，餘二即非真。","py":[]},{"t":"尹真人曰：九十六種外道，三千六百傍門，任他一切皆幻，只我這些是真。","py":[]},{"t":"雲房真人曰：道法三千六百門，人人各執一苗根，誰知些子玄關竅，不在三千六百門。","py":[]},{"t":"蓋玄天大道，難遇易成而見功遲。傍門小術，易學難成而見效速。是以貪財好色之徒，往往迷而不悟。","py":[]},{"t":"其中有好爐火者，有好彼家者，有視頂門者，有守臍蒂者，有運雙睛者，有守印堂者，有摩臍輪者，有搖夾脊者，有兜外腎者，有轉轆轤者，有三峯採戰者，有食乳對爐者，有閉息行氣者，有屈伸導引者，有三田還返者，有雙提金井者，有曬背臥冰者，有餌芝服術者，有納氣咽津者，有內視存想者，有休糧闢穀者，有忍寒食穢者，有搬精運氣者，有觀鼻調息者，有離妻入山者，有定觀鑒形者，有熊經鳥伸者，有餐霞服氣者，有長坐不臥者，有打七煉魔者，有禪定不語者，有齋戒斷味者，有夢遊仙境者，有默朝上帝者，有密咒驅邪者，有見聞轉誦者，有食己精為還元者，有捏尾閭為閉關者，有煉小便為秋食者，有采女經為紅鉛者，有抉陽用胞衣而煉紫河車者，有開關用黑鉛而鑄雌雄劍者，有閉目冥心而行八段錦者，有吐故納新而行六字氣者，有面壁而志在降龍伏虎者，有輕舉而思以駕風驂者，有吞精咽華以翕日月者，有步罡愎鬥以窺星辰者，有依卦爻之序而朝屯暮蒙者，有售黃白之術而燒茆弄火者，有希慕長生不死者，有馳志月日飛升者，有著相執而不化者，有著空流而不返者，有持戒定慧而望解脫者，有祛貪嗔癡而思清靜者，有生而願超西域者，有死而願登天堂者，似此泯泯棼棼，難以悉舉。","py":[]},{"t":"道釋者流，執此一術一訣，便謂金丹大道，止於是矣。籲！此輩如管中窺豹，井底觀天，妄引百端，支離萬狀，卒將至道，破段分門，以迷指迷，盲修瞎煉。不肯自思已錯，更將錯路教人。","py":[]},{"t":"是以王良器作破迷歌，陳泥丸作羅浮吟，鐘離翁作正道歌。曆舉傍門諸術之非，以救錯行邪徑之失也。","py":[]},{"t":"於中亦有數條，可以攻疾病，救老殘，益算延年，住世安樂。間或亦有超脫者，不過成個蓬島仙羅漢果耳。","py":[]},{"t":"故傅大士雲：饒經八萬劫，終是落空亡。此乃小乘功夫，不合大道全體。","py":[]},{"t":"故張平叔雲：學仙須是學天仙，唯有金丹最得端。","py":[]},{"t":"蓋金丹之道，簡而不繁。以虛無為體，以清靜為用。有作以成其始，無為以成其終。從首至尾，並無高遠難行之事。奈何世人，道在近而求諸遠，事在易而求諸難，背明投暗，不亦感乎？","py":[]},{"t":"夫金者，堅之稱；丹者，圓之喻，是人毗盧性海乾元面目。世尊名之，空不空，如來藏。老君號之：玄又玄，眾妙門。以此而言道，謂之無上至尊之道；以此而言法，謂之最上一乘之法。三教聖賢皆從此出修行正路。孰有正於此哉？","py":[]},{"t":"子之本懷，正欲乘此皇極昭明之世，與羣生同種乾元之因，共結龍華之伴，故作此說而挽邪歸正，並吾師所授諸圖訣竅明明指出，使諸學者印證丹經，一覽而無疑矣。","py":[]},{"t":"如此大法，萬神圭旨是也！","py":[]},{"t":"人之元氣逐日發生。子時複氣到尾間。醜時臨氣到背堂。寅時泰氣到玄樞。卯時大壯氣到夾脊。辰時書氣到陶道。已時乾氣到玉枕。午時垢氣到泥丸。未時豚氣到明堂。申時否氣到膻中。酉時觀氣到中浣。戍時剝氣到乾闕。亥時坤氣而歸於氣海矣。","py":[]},{"t":"人身有任督二脈，為陰陽之總。任脈者，起於中極之，下循腹裏，上關元至咽喉，屬陰脈之海。督脈者，起於下極之。腧穿脊裏，上風府，循額至鼻，屬陽脈之海。鹿運屬閭，蓋能通其督脈也。龜納鼻息，蓋能通其任脈也。人能通此二脈，則百脈皆通而無疾矣。","py":[]},{"t":"心者，君主之官，神明出焉。肺者，相傳之官，治節出焉。肝者，將軍之官，謀慮出焉。膽者，中正之官，決斷出焉。膻中者，臣使之官，喜樂出焉。脾者，倉稟之首，五味出焉。大腸者，傳道之官，變化出焉。小腸者，受盛之官，化物出焉。腎者，作強之官，技巧出焉。","py":[]},{"t":"腦者，髓之海，諸髓皆屬之，故上至泥丸，下至尾骶，俱腎主之。膻中，在兩乳間，為之之海，能分佈陰陽，為生化之源。故名之曰海膜，在肺下與助腹周圍，相著如幕，以遮濁氣，使不薰蒸上焦。幽門在大小腸之間，津液滲入膀胱。滓穢流入大腸，變化出矣。","py":[]},{"t":"普照圖之上一層者，直指心源性海之竅；中一層者，直指黃中正位之竅；下一層者，直指關元氣海之竅。此謂前三關也。","py":[]},{"t":"反照圖之下一層者，指出尾閭太玄之竅，中一層者，指出夾脊雙關之竅，上一層者，指出天穀泥丸之竅。此謂後三關也。丹陽雲：前三三，後三三，收拾起，一擔擔，是此義也。","py":[]},{"t":"時照圖者，發明陽升陽降之機，四象環中之妙。","py":[]},{"t":"內照圖者，指示五臟六腑、二十四椎、任督兩脈，使內觀者知有下手處。若人不明竅而言修，猶人未能立而言行也。從古諸仙皆口口相傳、心心相授，不敢明將此竅示人，是懼泄天機之故耳。吾師尹公開佛之正知見，等眾生如一子，繪此四圖接引後之迷者，意在普度有緣，同出生死苦海。","py":[]},{"t":"太極圖","py":[]},{"t":"此○者，釋曰圓覺，道曰金丹，儒曰太極。所謂無極而太極者，不可極而極之謂也。凡人始生之初，一點靈光而所以主張乎形骸者，太極也。父母未生以前，一片太虛而所以不屬乎形骸者，無極也。度師曰：欲識本來真面目，未生身處一輪月。","py":[]},{"t":"尹公曰：太極有二理，自運行而言則曰時候。雖天地不外乎一息，自凝結而言則曰真種。雖一黍可包乎天地，宿蟄、歸根、晏息、杳冥是為時侯太極。孕字、結實、交媾、結胎，是為真種太極。人能保完二極而無失，則可以長生不化，豈止盡年，令終而已哉。","py":[]},{"t":"太極發揮","py":[]},{"t":"大哉！吾身之太極。生生化化，與天地終。長生不化，超出天地。戒傷生，忌惡化，可以盡年，可以令終。絕其生，斷其化，可以長生，可以不化。盡年令終，與凡夫異；生長不化，與仙佛同。兩者皆從太極中出，而作用不同。","py":[]},{"t":"人皆知太極在未有天地萬物之先，而不知既有天地萬物，各有太極具焉。太極有時候、有真種。","py":[]},{"t":"未有天地萬物之太極，在戌亥二會。有此二會，太極斯有一元造化。每年太極在九月、十月，有此兩月太極，斯有一年造化。每月太極在二十六至三十，有此五日太極，斯有一月造化。每日太極在戌亥二時。有此二時，太極斯有一日造化。一時太極在窈窈冥冥二候，有此二候太極，所有一時造化。","py":[]},{"t":"動物太極在宿蟄孕字，植物太極在歸根結實，人身太極在晏息、窈冥、交媾、結胎。交媾有時，調養有法，不傷太極，此盡年令。終斷淫慾，時入窈冥，保完太極，此乃長生不化。盡年令終之道，亦有毀壞。長生不化之道，可以成仙，可以作佛，終無毀壞。豈直異於凡夫，別於草木禽獸云乎哉？","py":[]},{"t":"中心圖","py":[]},{"t":"此圖專指人心虛靈不昧一竅而說。這個竅原是廓然無際，神妙莫測的，原是渾然大中、不偏倚的，原是粹然至善、純一不雜的。昭昭乎本是圓明洞徹而無礙。以為有不睹不聞，奚所有也；以為無至靈至神，未嘗無也，本無方所亦無始終。","py":[]},{"t":"未有天地萬物之先，這個原是如此；既有天地萬物之後，這個只是如此，至無至有、至有至無，乃乾坤之靈體，元化之玄樞，人人性命之本原，天下萬物、萬事之大本。太易所謂太極四象、八卦皆由此出。大舜之謂中，孔子之謂一。帝王之授受，聖賢之相傳。明此便是克明峻德，知此便是知易，見此便是見道，立此便是立天下之大本，通此，性由我盡、命由我立，造化盡在我矣。","py":[]}]},{"h":"元集·火龍水虎說","paras":[{"t":"火龍水虎圖（五行顛倒術龍從火裏出，五行不順行虎向水中生）","py":[]},{"t":"夫黑鉛、水虎者，是天地發生之根，乃有質而有氣也。紅鉛、火龍者，是天地發生之本，乃有氣而無質也。有質者，真鉛也，大陰月之精也，為天地萬物育形之母。無質者，真汞也，太陽日之光也，為天地萬物發生之父。鉛汞之體，互相孽胤，迴圈不絕，可謂生天、生地，生萬物之祖宗也。","py":[]},{"t":"古之至人，知神物隱於此，假法象而採取太陰之精，設鼎器而誘會大陽之氣，使歸神室，混混相交，交合不已，孽產無窮，而水中生魂，金中生魄，魂魄凝然，化為鄞鄂，交結百寶，名曰金液還丹。","py":[]}]},{"h":"元集·日烏月兔說","paras":[{"t":"日烏月兔圖","py":[]},{"t":"日者，陽也。陽內含陰，象砂中有汞也。陽無陰，則不能自耀其魂，故名曰雌火，乃陽中含陰也。日中有烏，卦屬南方，謂之離女。故曰：日居高位反為女。","py":[]},{"t":"月者，陰也。陰內含陽，象鉛中有銀也。陰無陽，則不能自瑩其魄，故名曰雄金，乃陰中含陽也。月中有兔，卦屬北方，謂之坎男。故曰：坎配蟾宮卻是男。","py":[]},{"t":"無漏雲：鉛求玉兔腦中精，汞取金鳥心內血，只驅二物結成丹，至道不繁無扭捏。","py":[]},{"t":"悟真雲：先把乾坤為鼎器，次搏烏免藥來烹，既驅二物歸黃道，爭得金丹不解生。","py":[]},{"t":"二物者，一體也。","py":[]}]},{"h":"元集·大小鼎爐說","paras":[{"t":"大小鼎爐圖","py":[]},{"t":"凡脩金液大丹，必先安爐立鼎。鼎之為器，非金非鐵；爐之為具，非玉非石。黃庭為鼎，氣穴為爐。黃庭正在氣穴上，縷絡相連，乃人身百脈交匯之處。鼎卦曰：正位凝命是也。此謂之小鼎妒也。","py":[]},{"t":"乾位為鼎，坤位為爐。鼎中有水銀之陰，即火龍性根也。爐內有玉蕊之陽，即水成命蒂也。虎在下，為發火之樞機；龍居上，起騰雲之風浪。若爐內陽生陰降無差，則鼎中天魂地魄留戀，青龍與白虎相拘，玉免與金烏相抱。火候調停，煉成至寶。故青霞子曰：鼎鼎非金鼎，爐爐非玉爐。火從臍下發。水向頂中符。三姓既會合，二物自相拘。固濟胎不泄，變化在須臾。此謂之大鼎爐也。","py":[]}]},{"h":"元集·內外二藥說","paras":[{"t":"內外二藥圖（上葯三品，神與氣精，其體則一，其用則二，何謂體，本來三寳一體是也，何謂用，內外兩般作用是也，故悟真篇雲，內葯還同外葯，內通外亦須通，丹頭火熟自然紅，溫飬兩作用，此漸教也，權法也，接中根及下根人。大葯雖分神氣精，三般原是一根生，凡夫生死如輪轉，只因迷卻本來心，心即性也，故即然子曰，本來真性號金丹，四大為爐煉作圑，此頓教也，寔法也，接上根人及上上根人。）","py":[]},{"t":"凡修煉者，先修外藥，後修內藥。若高上之士，夙植靈根，故不煉外藥，便煉內藥。內藥無為無方。為外藥有為有以，為內藥無形無質。而實有外藥，有體有用。而實無外藥，可以治病，可以長生。久視內藥，可以超越，可以出有入無。外藥外陰陽往來，內藥內坎離輻輳。以外藥言之，交感之精，先要不漏，呼吸之氣，更要微微，思慮之神，貴在安靜。以內藥言之，煉精者，煉元精，抽坎中之元陽也，元精固，則交感之精自不洩漏；煉氣者，煉元氣，補離中之元陰也，元氣住，則呼吸之氣自不出入；煉神者，煉元神，坎離合體而複乾元，元神凝則思慮之神自然泰定。","py":[]},{"t":"內外兼修，成仙必矣。","py":[]}]},{"h":"元集·順逆三關說","paras":[{"t":"順逆三關圖","py":[]},{"t":"道生一、一生二、二生三、三生萬物，此所謂順去生人、生物。今則形化精、精化氣、氣化神、神化虛，此所謂逆來成仙、成佛。初關煉精化炁者，要識天癸生時，急急來之。採時須以徘徊之意，引火逼金行，顛倒轉自然，鼎內大丹凝。中關煉氣化神者，乘此火力熾盛，駕動河車，自太玄關逆流，至天穀穴，炁與神合，然後下降黃房。所謂乾坤交媾罷，一點落黃庭。上關煉神還虛者，守一抱元，以神歸於毗盧性海。","py":[]},{"t":"蓋三關自有為入無為者，漸法也。修上一關，兼下二關者，頓法也。若徑作煉神還虛者，工夫列虛極靜篤時，精自化炁，炁自化神。即關尹子忘精神而超生之上旨也。","py":[]}]},{"h":"元集·盡性了命說","paras":[{"t":"盡性了命圖","py":[]},{"t":"丹田喻日，心中元性喻月。日光自返照月，蓋交會之後實體乃生金也。月受日氣，故初三生一陽者，丹既居鼎，覺一點靈光自心常照而無晝夜。一陽生於月之八日而二陽產矣。二陽者，丹之金氣少旺，而元性又少現。自二陽生之於望而三陽純矣，三陽純者是所謂元性盡現而如月之圓矣。十六而一陰生，一陰者，性歸於命之始也。自一陰生至於月之二十三而二陰產矣。二陰者，乃性歸於命三之二也。自二陰生於月之三十日而三陰全矣。三陰金，乃性盡歸於命也。方其始也，以命而取性。性全矣，又以性而安命。","py":[]},{"t":"此是性命雙修大機括處。","py":[]}]},{"h":"元集·真土根心說","paras":[{"t":"真土圖","py":[]},{"t":"夫天之氣之所從生者，蓋蘊於天地之土中而無盡藏也。人之氣所從生者，蓋蘊於人身之土中而無盡藏也。故仁義禮智之根，根之心；猶草木之根，根於土。草木之根根於土，自然暢茂，而條達仁義禮智之根根於心，自然生色而啐面。孟子曰：居移氣，養移體。大學曰：心寬體胖。心既廣矣，體複胖矣，而謂病之不去體者，妄也。至若枝葉之或憔悴而枯槁也，則又如之何？亦唯直從於其根焉。而培之，而溉之，培之溉之而生意有不復息乎？蓋草木之根，病則枝葉病。若人之心猶草木之根也，心病則身病，心不病則身不病。故身病由於心病。而體胖，數語乃去病之聖藥也。","py":[]}]},{"h":"元集·魂魄說","paras":[{"t":"魂魄圖","py":[]},{"t":"鬼雲為魂，鬼白為魄。雲者，風，風者，木；白者，氣；氣者，金。風散故輕清，輕清者，魄從魂升。金堅故重濁，重濁者，魂從魄降。故聖人以魂運魄，眾人以魄攝魂。魂晝寓目，魄夜舍肝。寓目能見，舍肝能夢。夢多者，魄制魂；覺多者，魂勝魄。蓋因魄有精，因精有魂，因魂有神，因神有意，因意有魄。五者運行不已，所以我之偽心流轉造化幾億萬歲未有窮極。然核芽相生不知其幾萬株。天地雖大，不能芽空中之核；雌卵相生，不知其幾萬禽，陰陽雖妙，不能卵無雄之雌。是以聖人，萬物之來，對之以性而不對之以心。性者，心未萌也，無心則無意，無意則無魄，無魄則不受生，而輪回永息矣。","py":[]}]},{"h":"元集·蟾光說","paras":[{"t":"蟾光圖","py":[]},{"t":"太虛寥廓，皓月粲然，雪浪翻騰，金蟆吐耀。人見月之所以明而曰：金精盛則月明焉。孰知金之所以生者，自月而產也。人見金之產於月，而不知月之明本出於日也。月者，喻元性也。水，喻坎宮也。金蟆者，喻一點真陽之竅也。元性，喻月性之用也。性之初見，圓陀陀，光燦燦，狀似流星。蓋氣質之性稍息，而元神真性就見，如雲開則月現，霧散則陽暉。才見此物，分明便是元氣產矣，速急採取。譬之，見賊便捉，毋令再逸。收歸於鼎器之中，則一點元氣蟾光終，不可得而出矣。","py":[]}]},{"h":"元集·降龍說","paras":[{"t":"降龍圖","py":[]},{"t":"離日為汞，中有己土，強名曰龍。其形獰惡，主生人殺人之權，專成佛成仙之道，威能變化，感而遂通，雲行雨施，品物流行，乾之九二，見龍在田，利見大人。","py":[]},{"t":"子曰：龍德而正中也。世人不悟此龍生生之功，每服其害。若人悟而畏之，調而馭之，則能降此獰惡之龍而積至精之汞。降之者，制其心中真火，火性不飛，則龍可制而有得鉛之時。","py":[]},{"t":"故曰：不積汞，何以取其鉛，不降龍，無以伏其虎。且真鉛真汞未易相投，而真虎真龍亦難降伏。學道者若能了得這個字，其他事皆未務也。","py":[]}]},{"h":"元集·伏虎說","paras":[{"t":"伏虎圖","py":[]},{"t":"坎月為鉛，鉛中有戊土，強名曰虎，其形倡狂，雖能傷人殺人，卻蘊大乘氣象，舉動風威，叩之則應，舍弘光大品物資生文。","py":[]},{"t":"王重陽曰：履虎尾，不咥人。","py":[]},{"t":"亨又曰：愎道坦坦，幽人貞吉。","py":[]},{"t":"孔子曰：素愎之往，獨行願也。","py":[]},{"t":"若人悟而畏之，馴而調之，則能伏此倡狂之虎，以產先天之鉛。伏之者，伏身中真水，水源至清，則虎可伏而無咥人之害。","py":[]},{"t":"故歷代聖師以降龍為煉已，以伏虎為持心。是以純陽翁雲：七返還丹在人，先須煉己待時。","py":[]},{"t":"紫陽翁雲：若要修成九轉，先須煉己持心。皆此義也。","py":[]}]},{"h":"元集·三家相見說","paras":[{"t":"三家相見圖","py":[]},{"t":"身、心、意謂之三家。三家相見者，胎圓也。精、氣、神謂之三元。三元合一者，丹成也。攝三歸一，在乎虛靜。虛其心，則神與性合。靜其身，則精與情寂。意大定，則三元混一。","py":[]},{"t":"情合性謂之金木並，精合神謂之水火交，意大定謂之五行全。","py":[]},{"t":"然而精化為炁者，由身之不動也。炁化為神者，由心之不動也。神化為虛者，由意之不動也。心若不動，則東三南二同成五也。身若不動，則北一西方四共之也。意若不動，則戊己還生數五也。","py":[]},{"t":"身，心、意合，則三家相見，結嬰兒也。","py":[]}]},{"h":"元集·和合四象說","paras":[{"t":"和合四象圖","py":[]},{"t":"四象者，青龍、白虎、朱雀、玄武也。五行者，金、木、水、火、土也。龍木生火，同矚乎心。心者，象帝之先靈妙，本有中之真無也。心若不動，則龍吟雲起。朱雀斂翼，而元氣聚矣。虎金生水，同系乎身。身者，曆劫以來清靜，自無中之妙有也。身若不動，則虎嘯風生。玄龜潛伏，而元精凝矣。精凝氣聚，則金木水火混融於真土之中，而精神魂魄攢簇於真意之內。真意者，乾元也。乃天地之母，陰陽之根，水火之本，日月之宗，三才之源，五行之祖，萬物賴之以生成，千靈承之以舒慘。意若不動，則二物交、三寶結、四象和合、五行攢簇，俱會八中宮而大丹成矣。故紫陽雲：五行全要八中央。蓋此之謂也。","py":[]}]},{"h":"元集·取坎填離說","paras":[{"t":"取坎填離圖","py":[]},{"t":"鉛汞者，太極初分，先天之炁也。先天炁者，龍虎初弦之炁也。虎居北方坎水之中，而坎中陽爻原屬於乾。劫運未交之先，乾因顛蹶馳驟誤陷於坤。乾之中爻損而成離。離本汞居，故曰，坎內黃男名汞祖也。龍居南方離火之內，而離中陰爻原屬於坤，混沌顛落之後，坤因含受孕育，得配於乾。坤之中爻實而為坎，坎本鉛會，故曰離中玄女是鉛家也。似此男女異室，鉛汞異爐，陰陽不交，則天地否矣。聖人以意為黃婆，引坎內黃男，配離中玄女。夫妻一媾，即變純乾，謂之取坎填離，複我先天本體。故悟真篇雲：取將坎內中心實，點化離宮腹內陰，正此義也。","py":[]}]},{"h":"元集·念觀音咒說","paras":[{"t":"觀音密呪圖（始則自上而下至於臍中，唵字須要到臍；終則自下而上至於喉內，𡄣字在臍之下）","py":[]},{"t":"此咒是觀音菩薩微妙心印。若人書寫六字大明咒者，即同書寫三藏法寶；若人得念六字大明咒者，則同諷誦七軸靈文。又能開智慧門，能救百難苦，三世業冤，悉皆清靜，一切罪障，盡得消除，解脫生死，安樂法身。然而唸咒亦有密訣。故第一聲中叫唵之，乃以呼吾身毗盧遮那佛也。第二聲東而嘛之，乃以呼吾身不動尊佛也。第三聲南而呢之，乃以呼吾身寶生佛也。第四聲西而叭之，乃以呼吾身無量壽佛也。第五聲北而咪之，乃以呼吾身不空成就佛也。第六聲複上返於喉而作吽者，乃以呼吾身大勢至金剛也。久則五炁歸元，即成就不思議功德而證圓通也。","py":[]}]},{"h":"元集·九鼎煉心說","paras":[{"t":"九鼎煉心圖","py":[]},{"t":"日也者，天之丹也，黑而蕩之，則日不丹。心也者，人之丹也，物而霾之，則心不丹。故煉丹也者，煉去陰霾之物，以複其心之本體天命之性之自然也。天命之性，吾之真金也，人人之所必有者。氣質之性，金之濁渣也。上智之所不無者，若以人倫日用之火而日煉之，則氣質之性日除。氣質之性日除，則天命之性自見矣。故五帝三王君也，而以君道而日煉其心；伊博周召相也，而以相道而日煉其心，孔曾思孟師也，而以師道而日煉其心。無時而不心在於道，無時而不以道而煉其心，此乃古大聖大賢為學之要法，百煉、煉心、煉性之明訓也。","py":[]}]},{"h":"元集·八識歸元說","paras":[{"t":"八識歸元圖","py":[]},{"t":"釋氏謂，人之受生，必從父精母血與前生之識神三相合而後成胎。精氣受之父母，神識不受之父母也。蓋從無始劫流來，亦謂之生滅性。故曰：生滅與不生滅和合而成八識也。蓋造化間有個萬古不移之真宰，又有個與時推移之氣運。真宰與氣運合是謂天命之性。天命之性者，元神也。氣質之性者，識神也。故儒家有變化氣質之言，禪宗有返識為智之法。今人妄認方纔中有個昭昭靈靈之物，渾然與物同體，便以為元神在。是殊不知此即死死生生之本，非不生不滅之元神也。噫，識識易，去識難，若不以天命元神戰退無明業識。終在生滅場中，未見有出頭日也。","py":[]}]},{"h":"元集·五氣朝元說","paras":[{"t":"五氣朝元圖","py":[]},{"t":"一氣初判而列二儀，二儀定位而分五常，五常異地而各守一方，五方異氣而各守一子。青帝之子名龍煙，受甲乙木德之三氣。赤帝之子名丹元，受丙丁火德之二氣。白帝之子名皓華，受庚辛金德之四氣。黑帝之子名玄冥，受壬癸水德之一氣。黃帝之子名常存，受戊己土德之五氣。故金得土則生，木得土則旺，水得土則止，火得土則息。唯聖人知回幾之道、得還元之理。於是攢五、簇四、會三、合二而歸一也。蓋身不動則精固而水朝元，心不動則氣固而火朝元，真性寂則魂藏而木朝元，妄情忘則魄伏而金朝元，四大安和則意定而土朝元。此謂五氣朝元，皆聚於頂也。","py":[]}]},{"h":"元集·待詔說","paras":[{"t":"待詔圖（形神俱妙道為徒，性命相圓合太虛，寳詔降時騰鶴馭，玉書拜後駕龍車，龍車冉冉乘雲氣，遍滿六虛廣無際，九天仙子笑相迎，同詣玄都朝上帝）","py":[]},{"t":"九年面壁之後。靈臺晶瑩，覺海圓明，性命混融，形神俱妙。與天地合德，與太虛同體，此同丹道已成而積功累行不可缺也。蓋道之與德猶陰之與陽，行之與功猶日之與足。鐘離翁雲：有功無行如無足，有行無功目不全。功行兩圓足自備，誰雲無分作神仙？是以古仙上聖金丹事成，溫養事畢，遊戲人間，和光混俗，隨力建功，隨方解縛，扶危拯厄，救劫匡時，普渡羣迷，接引後學，道上有功，人間有行。功行滿足，潛伏俟時，只待天書降詔，玉女來迎，駕霧騰雲，直入三清聖境。如張紫陽翁悟真篇雲：德行修逾八百，陰功積滿三千，寶符降詔去朝天，穩駕瓊輿鳳輦。","py":[]}]},{"h":"元集·飛昇說","paras":[{"t":"飛昇圖","py":[]},{"t":"仙有五等，佛有三乘，修持功行不齊，所以超脫稍異。飛升沖舉者上也，坐化屍解者次也，投胎奪舍者又其次也。乘龍上升者，如黃帝、茅蒙、王玄甫、韋善俊是也。駕雲上升者，如楊羲、李笈、藍採和、孫不二是也。控鯉上升者，如子英、琴高是也。驂鸞上升者，如子晉、鄧鬱是也。跨鶴上升者，如桓問、屈處靜是也。御風上升者，如葛由、武夷君是也。拔宅飛升者，如何候、尹喜、淮南王、許旌陽是也。白日沖舉者，如蔡瓊、馮長、馬成子、浮丘伯是也。嘗考到仙譜傳，始知從古至今成仙者十萬餘人，拔宅者八千餘處。所以純陽翁於景福寺壁間題一聯雲：莫道神仙無學處，古今多少上昇人。","py":[]}]},{"h":"亨集·涵養本原救護命寶","paras":[{"t":"涵養本原救護命寶","py":[]},{"t":"涵養本原圖","py":[]},{"t":"（內附退藏沐浴、玉液煉形二法）","py":[]},{"t":"欲修長生，須識所生之本；欲求不死，當明不死之人。故曰：認得不死人，方纔人不死。那不死的人，道家呼為鐵漢，釋氏喚作金剛，即世人本來妙覺真心是也。","py":[]},{"t":"此心靈靈不昧、了了常知，其體不生不滅，其相無去無來。究之，於先天地之先，莫知其始；窮之，於後天地之後，莫知其終。高而無上，廣不可極；淵而無下，深不可測。乾坤依此而覆載，日月依此而照臨，虛空依此而寬廣，萬靈依此而變通。","py":[]},{"t":"三教大聖，教人修道，是修這個；成仙成佛，也是這個；戴角披毛，也是這個。","py":[]},{"t":"聖凡二路，由此而分。出生死，再無別途；登涅槃，唯此一法。然世間萬彚，未有一物不被無常所吞，獨有這個，無生滅可縛，無色相可窺，端端正正，停停當當，分分曉曉的，而人不悟其所本來也。","py":[]},{"t":"不悟者何，為有妄心。何為妄心？蓋為一切眾生從無始已來，迷卻真心，不自覺知，故受輪轉，枉入諸趣，原夫真心無妄，性智本明，妙湛元精。由妄瞥起，俄然晦昧，則失彼元精，粘湛發知，故轉智為識，形中妄心，名之曰識。","py":[]},{"t":"心本無知，由識故知；性本無生，由識故生。生身種子，萌櫱於茲，開有漏華，結生死果。今人妄認方寸中，有個昭昭靈靈之物，渾然與物同體，便以為元神在是。殊不知此即死死生生之識神，劫劫輪回之種子耳。","py":[]},{"t":"故景岑雲：學道之人不悟真，只為從前認識神，無量劫來生死本，癡人喚作本來人。","py":[]},{"t":"嗟夫！世人以奴為主而不知，認賊為子而不覺。是以世尊教人：先斷無始輪回根本者此也。此根既斷，則諸識無依，複我元初常明本體。","py":[]},{"t":"然而大道茫茫，當從何處下手？是以齊襟必舉領，整網要提綱。昔尹師指出：修行正路一條。教人打從源頭上做起。若源頭潔淨，天理時時現前，識念自然污染不得。譬如昊日當空，魍魎滅跡，此一心地法門，是古今千聖不易之道。","py":[]},{"t":"故老子曰：若夫修道，先觀其心。觀心之法，妙在靈關一竅。人自受生感氣之初，稟天地一點元陽，化生此竅，以藏元神。其中空空洞洞，至虛至明，乃吾人生生主宰。真所謂有之則生，無之則死，生死盛衰，皆由這個。","py":[]},{"t":"儒曰：靈臺。","py":[]},{"t":"道曰：靈關。","py":[]},{"t":"釋曰：靈山。","py":[]},{"t":"三教同一法門，總不外此靈明一竅。","py":[]},{"t":"釋教曰：佛在靈山莫遠求，靈山只在汝心頭，人人有個靈山塔，好向靈山塔下修。論其所也。","py":[]},{"t":"玄教曰：大道根莖識者稀，常人日用孰能知，為君指出神仙窟，一竅彎彎似月眉。論其形也。","py":[]},{"t":"蓋此竅乃神靈之臺，祕密之府。真淨、明妙、虛徹、靈通、卓然而獨存者也。眾生之本原，故曰心地。諸佛之所得，故曰菩提。交徹融攝，故曰法界，寂靜常樂，故曰涅槃。不濁不漏，故曰清淨。不妄不變，故曰真如。離過絕非，故曰佛性。護善遮惡，故曰總持。隱覆含攝，故曰如來藏。超越玄祕，故曰密嚴國。統眾德而大備，爍羣昏而獨照，故曰圓覺。其實皆一竅也。背之則凡，順之則聖。迷之則生死始，悟之則輪回息。","py":[]},{"t":"欲息輪回，莫若體乎至道。欲體至道，莫若觀照本心。欲照本心，應須普眼虛鑒，常教朗月輝明，每向定中慧照。時時保得此七情未發之中，時時全得此八識未染之體。外息諸緣，內絕諸妄。含眼光，凝耳韻，調鼻息，緘舌氣，四肢不動，使眼耳鼻舌身之五識，各返其根，則精神魂魄意之五靈各安其位。","py":[]},{"t":"二六時中，眼常要內觀此竅，耳常要逆聽此竅，至於舌準常要對著此竅，運用施為念念不離此竅，行住坐臥心心常在此竅。不可剎那忘照，率爾相違，神光一出便收來，造次弗離常在此。即子思所謂不可須臾離者是也。","py":[]},{"t":"先存之以虛其心，次忘之以廓其量，隨處隨時，無礙自在，正合龍虎經雲：至妙之要，先存後忘。此又口訣中之口訣也。","py":[]},{"t":"然要進除六識，尤在知所先後。意雖為六識之主帥，眼實為五賊之先鋒。故古德雲：心是樞機，目為盜賊。欲伏其心，先攝其目。蓋弩之發動在機，心之緣引在目。機不動則弩住，目不動則心住。","py":[]},{"t":"陰符經曰：機在目。","py":[]},{"t":"道德經曰：不見可欲，而心不亂。","py":[]},{"t":"魯論曰：非禮勿視。","py":[]},{"t":"朱子曰：制於外所以養其中也。","py":[]},{"t":"金笥寶籙曰：眼乃神遊玄牝門，抑之於眼使歸心。","py":[]},{"t":"眼守此竅不離，即如來正法眼，合涅槃心之祕旨，故楞嚴經雲：作是觀者，名為正觀；若他觀者，名為邪觀。","py":[]},{"t":"又觀經觀心品雲：三界之中，以心為主。能觀心者，究竟解脫；不能觀者，畢竟沉淪。","py":[]},{"t":"道德首章雲：常有欲以觀其徼者，觀此竅也。常無欲以觀其妙者，觀此竅中之妙也。","py":[]},{"t":"昔黃帝三月內觀者，觀此也。","py":[]},{"t":"太上亦曰：吾從無量劫來，觀心得道，乃至虛無。","py":[]},{"t":"觀心非易，止念尤難。是以念頭起處，系人生死之根。","py":[]},{"t":"古仙雲：大道教人先止念，念頭不住亦徒然。","py":[]},{"t":"圓覺經雲：居一切時，不起妄念。於諸妄心，亦不息滅。住妄想境，不加了知。於無了知，不辨真實。","py":[]},{"t":"起信論雲：心若馳散，即便攝來，令住正念，念起即覺，覺之即無，修行妙門，唯在於此。","py":[]},{"t":"虛靖天師雲：不怕念起，只怕覺遲，念起是病，不續是藥。","py":[]},{"t":"當知妄念起於識根，闘境成妄，實非有體。在眾生時，智劣識強，但名為識。當佛地時，智強識劣，但名為智。秪轉其名，不轉其體。初一心源廓然妙湛，由知見立知，妄塵生起，故有妄念。若知見無見，則智性真淨，復還妙湛，洞徹精了，而意念消。","py":[]},{"t":"意念既消，自六識而下莫不皆消。即文殊所謂一根既返元，六根成解脫。既無六根，則無六塵。既無六塵，則無六識。既無六識，則無輪回種子。既無輪回種子，則我一點真心獨立無依，空空蕩蕩，光光淨淨，而萬劫常存，永不生滅矣。","py":[]},{"t":"此法直指人心，一了百當。何等直截，何等簡易。但能培養本原，觀照本竅，久則油然心新，浩然氣暢，凝然不動，寂然無思，豁然知空，瞭然悟性。此所謂皮膚剝落盡，一真將次見矣。","py":[]},{"t":"工夫至此，自然精神朗發，智慧日生，心性靈通，隱顯自在。自然有一叚清寧闔闢之機，自然有一叚飛躍活動之趣。自然有一點元陽真炁從中而出，降黃庭，入土釜，貫尾閭，穿夾脊，上沖天穀，下達曲江，流通百脈，灌溉三田，驅逐一身百竅之陰邪，滌蕩五臟六腑之濁穢。如服善見王之藥，眾病鹹消。若奏獅子筋之弦，羣音頓絕。所以雲：一心療萬病，不假藥方多。","py":[]},{"t":"是知一切諸聖，皆從此心方便門入，得成祖佛，為人天之師。凡夫不能證者，由不識自心故。故曰：海枯終見底，人死不知心。六道羣蒙皆此門出，曆千劫而不返，一何痛哉。","py":[]},{"t":"所以諸佛驚入火宅，祖師特地西來，乃至千聖悲嗟，皆為不達唯心出要道耳。","py":[]},{"t":"如寶藏論雲：夫天地之內，宇宙之間，中有一寶，祕在形山，識物靈照，內外空然，寂寞難見，其謂玄玄。巧出於紫微之表，用在於虛無之間。端化不動，獨而無雙。聲出妙響，色吐華容。窮睹無所，寄號空空。唯留其聲，不見其形。唯留其功，不見其容。幽顯朗照，物理虛通。森羅寶印，萬象真宗。其為也形，其寂也冥。本淨非瑩，法爾圓成。光超日月，德越太清。萬物無作，一切無名。轉變天地，自在縱橫。恆沙妙用，混沌而成。誰聞不喜，誰聞不驚。如何以無價之寶，隱於陰入之坑。哀哉！哀哉！其為自輕。悲哉！悲哉！晦何由明？其寶也煥煥煌煌，朗照十方，闃寂無物，應用堂堂。應聲應色，應陰應陽。奇物無根，妙用常存。瞬目不見，側耳不聞。其本也冥，其化也形。其為也聖，其用也靈。可謂大道之真精，其精甚靈，萬有之因。凝然常住，與道同倫。","py":[]},{"t":"天下最親，莫過心也。百姓日用，而不知心；如魚在海，而不知水。故佛經雲：一切眾生，從曠劫來，迷倒本心，不自覺悟。妄認四大為身、緣慮為心。譬如百千大海不認，但認一小浮漚。以此迷中復迷，妄中起妄，隨境流轉，寓目生情。取捨萬端，無時暫暇。至使起惑造業，循環六道，密網自圍，不能得出。究竟冥初，皆一妄迷真之咎耳。","py":[]},{"t":"故靈潤曰：妄情牽引何時了，辜負靈臺一點光。夫靈臺一點光者，即真如靈知心也。最玄最妙，通聖通靈。極高明，極廣大。化萬法之王，為羣有之體。堅徹三界，橫亙十方。自混沌未闢之前，而已曾有。雖天地既壞以後，而未嘗無。一切境界，皆是心光。若人識得心，大地無寸土。故曰：三界唯心。","py":[]},{"t":"迷人心外求法，至人見境是心。境是即心之境，心是即境之心。對境不迷，逢緣不動，能所互成，一體無異。若能達境唯心，便是悟心成道，覺盡無始妄念，攝境歸心，出纏真如，離垢解脫，永合清淨本然，則不更生山河大地諸有為相。如金出礦，終不更染塵泥；似木成灰，豈有再生枝葉。一得永得，盡未來際，永脫樊籠，長居聖域矣。","py":[]},{"t":"雖然，此最上一乘大道，若根器利者，一超直入如來地。若根器鈍者，將如之何？必由下學而上達的功夫，漸次引入法門可也。使之行一步，自有一步效驗，升一級，自有一級規模。亦是行遠自邇，登高自卑之意。","py":[]},{"t":"若不知入門下手功夫，安能遽到了手極則地位？若未能盡心，而安能知性？未能明心，而安能見性？夫明心盡心之要者，時以善法扶助自心，時以赤水潤澤自心，時以境界淨治自心，時以精進堅固自心，時以忍辱坦蕩自心，時以覺照潔白自心，時以智慧明利自心，時以佛知見開發自心，時以佛平等廣大自心。","py":[]},{"t":"故知明心是生死海中之智楫，盡心是煩惱病中之良醫。若昧此心，則永劫輪回而遺失真性；若明此心，則頓超生死而圓證涅槃。始終不出此心，離此心別無玄妙矣。後面雖有次第工夫，不過是成就這個而已。","py":[]},{"t":"噫！莫看易了，至人難遇，口訣難聞。故張平叔雲：只為丹經無口訣，教君何處結靈胎？殊不知經中口訣自載，大都祕母言子，不肯分開說破，使人湊泊不來。況多為譬辭隱語，使學者眩目惑心，以致中途退步。餘甚憫之，今將丹經梵典中之口訣，一一拈出，留與後人，為破昏黑的照路燈，辨真偽的試金石。","py":[]},{"t":"太玄真人云：","py":[]},{"t":"父母生前一點靈，不靈只為結成形。成形罩卻光明種，放下依然徹底清。","py":[]},{"t":"空照禪師雲：","py":[]},{"t":"這個分明個個同，能包天地運虛空。我今直指真心地，空寂靈知是本宗。","py":[]},{"t":"自然居士雲：","py":[]},{"t":"心如明鏡連天淨，性似寒潭止水同。十二時中常覺照，休教昧了主人翁。","py":[]},{"t":"智覺禪師雲：","py":[]},{"t":"菩薩從來不離真，自家昧了不相親。若能靜坐回光照，便見生前舊主人。","py":[]},{"t":"三茅真君雲：","py":[]},{"t":"靈臺湛湛似冰壺，只許元神在裏居。若向此中留一物，豈能證道合清虛？","py":[]},{"t":"天然禪師雲：","py":[]},{"t":"心本絕塵何用洗，身中無病豈求醫。欲知是佛非身處，明鑒高懸未照時。","py":[]},{"t":"主敬道人云：","py":[]},{"t":"未發之前心是性，已發之後性是必。心性源頭參不透，空從往跡費搜尋。","py":[]},{"t":"無心真人云：","py":[]},{"t":"妄念才興神即遷，神遷六賊亂心田。心田既亂身無主，六道輪回在目前。","py":[]},{"t":"高僧妙虛雲：","py":[]},{"t":"惺惺一個主人翁，寂然不動在靈宮。但得此中無掛礙，天然本體自虛空。","py":[]},{"t":"太乙真人云：","py":[]},{"t":"一點圓明等太虛，只因念起結成軀。若能放下回光照，依舊清虛一物無。","py":[]},{"t":"華嚴經頌雲；","py":[]},{"t":"有數無數一切劫，菩薩了知即一念。於此善入菩提行，常勤修習不退轉。","py":[]},{"t":"海月禪師雲：","py":[]},{"t":"六個門頭一個關，五門不必更遮攔。從他世事紛紛亂，堂上家尊鎮日安。","py":[]},{"t":"水庵禪師雲：","py":[]},{"t":"不起一念須彌山，待立當頭著眼看。拈一縷絲輕絆倒，家家門底透長安。","py":[]},{"t":"大溈智頌雲：","py":[]},{"t":"真佛無為在我身，三呼三應太惺惺。若人不悟原由者，生劫茫茫認識神。","py":[]},{"t":"無垢子謁雲：","py":[]},{"t":"五蘊山頭一段空，同門出入不相逢。無量劫來賃屋住，到頭不識主人翁。","py":[]},{"t":"惟寛禪師雲：","py":[]},{"t":"勸君學道莫貪求，萬事無心道合頭。無心始體無心道，體得無心道也休。","py":[]},{"t":"志公和尚雲：","py":[]},{"t":"頓悟心原開寶藏，隱顯靈蹤現真相。獨行獨坐常巍巍，百億化身無數量。","py":[]},{"t":"獃堂禪師雲：","py":[]},{"t":"應無所住生其心，廓徹圓明處處真。直下頂門開正眼，大千沙界現全身。","py":[]},{"t":"指玄篇雲：","py":[]},{"t":"若得心空若便無，有何生死有何拘。一朝脫下胎州襖，作個逍遙大丈夫。","py":[]},{"t":"段真人云：","py":[]},{"t":"心內觀心覓本心，心心俱絕見真心。真心明徹通三界，外道天魔不敢侵。","py":[]},{"t":"張遠霄雲：","py":[]},{"t":"不生不滅本來真，無價夜光人不識。凡夫虛度幾千生，雜在礦中不能出。","py":[]},{"t":"薛道光雲：","py":[]},{"t":"妙訣五千稱道德，真詮三百頌陰符。但得心中無一字，不參禪亦是工夫。","py":[]},{"t":"無垢子云：","py":[]},{"t":"學道先須識自心，自心深處最難尋。若還尋到無尋處，方悟凡心即佛心。","py":[]},{"t":"逍遙翁雲：","py":[]},{"t":"掃除六賊淨心基，榮辱悲歡事勿追。專炁至柔窺內景，自然神室產牟尼。","py":[]},{"t":"弄丸集雲：","py":[]},{"t":"天機奧妙難輕吐，顏氏如愚曾氏魯。問渠何處用工夫，只在不聞與不睹。","py":[]},{"t":"張三豐雲：","py":[]},{"t":"真心浩浩無窮極，無限神仙從裏出。世人耽著小形骸，一顆玄珠迷不識。","py":[]},{"t":"解迷歌雲：","py":[]},{"t":"若要真精無漏泄，須淨靈臺如朗月。靈臺不淨神不清，晝夜工夫休斷絕。","py":[]},{"t":"北塔祚雲：","py":[]},{"t":"切忌隨他不會他，大隨此語播天涯。真淨性中纔一念，早是千差與萬差。","py":[]},{"t":"橫川拱雲：","py":[]},{"t":"洞水無緣會逆流，見他苦切故相酧。西來祖意寔無意，妄想狂心歇便休。","py":[]},{"t":"草堂禪師雲：","py":[]},{"t":"斷臂覓心心不得，覓心無得始安心。心安後夜雪庭際，滿目瑤花無處尋。","py":[]},{"t":"佛國禪師雲：","py":[]},{"t":"心心即佛佛心心，佛佛心心即佛心。心佛悟來無一物，將軍止渴望梅林。","py":[]},{"t":"華嚴經偈雲：","py":[]},{"t":"若人慾識佛境界，當淨其意即虛空。遠離妄想及諸取，令心所向皆無礙。","py":[]},{"t":"寶積經頌雲：","py":[]},{"t":"諸佛從心得解說，心者清淨名無垢。五道鮮潔不受染，有解此者成大道。","py":[]},{"t":"圓悟禪師雲：","py":[]},{"t":"佛佛道同同至道，心心真契契真心。廓然透出威音外，地久天長海更深。","py":[]},{"t":"世奇首座雲：","py":[]},{"t":"諸法空故我心空，我心空故諸法同。諸法我心無別體，只在而今一念中。","py":[]},{"t":"張拙秀才雲：","py":[]},{"t":"光明寂照遍河沙，凡聖原來共一家。一念不生全體現，六根才動被雲遮。","py":[]},{"t":"中峯禪師雲：","py":[]},{"t":"從來至道與心親，學到無心道即真。心道有無俱泯絕，大千世界一閑身。","py":[]},{"t":"張無夢雲：","py":[]},{"t":"心在靈關身有主，氣歸元海壽無窮。","py":[]},{"t":"白沙先生雲：","py":[]},{"t":"千修千處得，一念一生持。","py":[]},{"t":"彭鶴林雲：","py":[]},{"t":"神室即是此靈合，中有長生不死胎。","py":[]},{"t":"永明延壽雲：","py":[]},{"t":"有念即生死，無念即泥洹。","py":[]},{"t":"胡敬齋雲：","py":[]},{"t":"無事時不教心空，有事時不教心亂。","py":[]},{"t":"道玄居士雲：","py":[]},{"t":"一出便收來，既歸須放下。","py":[]},{"t":"羅念庵雲：","py":[]},{"t":"毋以妄念伐其心，母以客氣傷元氣。","py":[]},{"t":"莎衣道人云：","py":[]},{"t":"心若在腔子裏，念不出總持門。","py":[]},{"t":"白樂天雲：","py":[]},{"t":"自從苦學空門法，消盡平生種種心。","py":[]},{"t":"淨業禪師雲：","py":[]},{"t":"動不忘於觀照，靜不忘於止息。","py":[]},{"t":"韜光集雲：","py":[]},{"t":"心在是念亦在是，動如斯靜也如斯。","py":[]},{"t":"沖妙雲：","py":[]},{"t":"身不動而心自安，心不動而神自守。","py":[]},{"t":"徐無極雲：","py":[]},{"t":"性從偏處克將去，心自放時收拾來。","py":[]},{"t":"佛印雲：","py":[]},{"t":"一念動時皆是火，萬緣寂處即生春。","py":[]},{"t":"陶宏景雲：","py":[]},{"t":"修心要作長生客，煉性當如活死人。","py":[]},{"t":"無着禪師雲：","py":[]},{"t":"明即明心空寂，見即見性無生。","py":[]},{"t":"華嚴經雲：","py":[]},{"t":"若能諦觀心不二，方見毗盧清淨身。","py":[]},{"t":"華嚴頌雲：","py":[]},{"t":"始從一念終成劫，悉依眾生心想生。","py":[]},{"t":"馬丹陽雲：","py":[]},{"t":"若能長守彎彎竅，神自靈明氣自充。","py":[]},{"t":"丘長春雲：","py":[]},{"t":"當時一句師邊得，默默垂簾仔細看。","py":[]},{"t":"慧日禪師雲：","py":[]},{"t":"一念照了一念之菩提也，一念晏息一會之涅槃也。","py":[]},{"t":"以上數語，皆成仙作聖之要、入道入德之門也。首阿難多聞總持積歲不登聖果，息緣返照，暫時即證無生。蓋凡夫之心，終日趣外，愈遠愈背。唯返照者，檢情攝念，攝念安心，安心養神，養神歸性。即魏伯陽所謂金來歸性初，乃得稱還丹是也。咦！煉礦成金得寶珍，煉情歸性合天真。相逢此理，交談者千萬人中無一人。","py":[]},{"t":"退藏沐浴工夫","py":[]},{"t":"洗心退藏圖","py":[]},{"t":"易之洗心退藏於密這句話頭，唐宋神仙謂之沐浴，近代諸人標為艮背，總只是這個道理，這個竅妙。原夫心屬乎火，而藏之以背之水者，洗之之義也，心居乎前，而藏之以背之後者，退之之義也。","py":[]},{"t":"故初機之士，降伏其心，束之太緊，未免有煩燥火炎之患，是以暫將心火之南而藏背水之北，水火互相交養，自然念慮不生。即白玉蟾所謂洗心滌慮為沐浴是也。","py":[]},{"t":"然沐浴雖為洗心之法，艮背雖有止念之功，二理是則是矣，皆未到實際之地。此向上一著，千聖祕而不傳後世。學徒所以罕聞、罕遇。人若明得此竅，真可以奪神功，改天命。","py":[]},{"t":"古仙有言曰：夾脊雙關透頂門，修行徑路此為尊。以其上通天穀，下達尾閭，中通心腎，召攝靈陽，救護命寶。此非修行徑路而何？吾人未有此身，先有此息，此身未滅，此息先滅，此又非修行正路而何？","py":[]},{"t":"原人受生之初，在胞胎內隨母呼吸，受氣而成此縷，與母聯屬，漸吹漸開，中空如管，通氣往來，前通於臍，後通於腎，上通夾脊泥丸，至山根而生雙竅，由雙竅下至準頭，而成鼻之兩孔，是以名曰鼻祖。","py":[]},{"t":"斯時，我之氣通母之氣，母之氣通天地之氣，天地之氣通太虛之氣，竅竅相通，無有隔閡。及乎氣數滿足，裂胞而出，剪斷臍帶，㘞地一聲，一點元陽落於立命之處。自此後天用事，雖有呼吸往來，不得與元始祖氣相通。人生自幼至老，未有一息駐於其中。凡夫塵生塵滅，萬死萬生，只為尋不著來時舊路耳。","py":[]},{"t":"太上立法，教人修煉而長生者，由其能奪天地之正氣。人之所以能奪天地之正氣者，由其有兩孔之呼吸也。所呼者自己之元氣從中而出，所吸者天地之正氣從外而入。人若根源牢固，呼吸之間，亦可以奪天地之正氣而壽綿長。人若根源不固，精竭氣弱，所吸天地之正氣隨呼而出，身中元氣不為己之所有，反為天地所奪。何也？蓋為呼吸不得其門而入耳。","py":[]},{"t":"一切常人，呼吸皆從咽喉而下，至中脘而回，不能與祖氣相連，如魚飲水而口進腮出，即莊子所謂，眾人之息以喉是也。","py":[]},{"t":"若是至人，呼吸直貫明堂而上，至夾脊而流入命門，得與祖氣相連，如磁吸鐵，而同類相親。即莊子所謂，真人之息以踵是也。踵者，其息深深之義。既得深深，則我命在我，而不為大冶陶鑄矣。","py":[]},{"t":"今之人，有調息、數息、抑息、閉息，皆是隔靴搔癢，不得到於玄竅。","py":[]},{"t":"此竅初凝，就生兩腎，次生其心。其腎如藕，其心如蓮，其梗中通外直，拄地撐天。心腎相去八寸四分，中餘一寸二分，謂之腔子裏是也，乃心腎往來之路，水火既濟之鄉。","py":[]},{"t":"欲通此竅，先要存想山根，則呼吸之氣漸次通夾脊，透混元，而直達於命府，方纔子母會合，破鏡重圓，漸漸擴充，則根本完固，救住命寶，始可言其修煉。按了真子曰：欲點常明燈，當用添油法。尹師曰：涵養本原為先，救護命寶為急。又曰：一息尚存，皆可複命。人若知添油之法，續盡燈而複光明，即如得返魂之香，點枯荄而重茂盛。所以雲：油乾燈滅，氣絕身亡。然非此竅則不能添油，非添油則不能接命，命不接則留性不住，性不住忽一旦無常到來，則懵懵然而去矣。故呂公曰：嗇精宜及早，接命莫教遲。果然是接之則長生，不接則夭死。","py":[]},{"t":"蓋人稟天地氣數有限，不知保養，自暴自棄，如劉海蟾雲：朝傷暮損迷不知，喪亂精神無所據；細細消磨漸漸衰，耗竭元和神乃去。闔闢之機一停，呼吸之氣立斷。嗚呼！生死機關，其速如此，世人何事而不肯回心向道耶？","py":[]},{"t":"況此著工夫最是簡易，不拘行住坐臥，常操此心，退藏夾脊之竅，則天地之正氣可扯而進，與己混元真精凝結丹田，以為超生之本。蓋以天地無涯之元炁，而續我有限之形軀，不亦易乎？","py":[]},{"t":"學者只要認定此竅，守而不離，久久純熟，則裏面皎皎明明，如月在水相似，自然散其邪火，銷其雜慮，降其動心，止其妄念。妄念既止，真息自現，真念無念，真息無息。息無則命根永固，念無則性體恆存。性存命固、息念俱銷，此性命雙修之第一步也。","py":[]},{"t":"嗟乎！人生如無根之樹，全憑氣息以為根株，一息不來，命非己有。故欲修長生者，必固其氣。氣固則身中之元氣不隨呼而出，天地之真氣恆隨吸而入。久之，胎息定，鄞鄂成，而長生有路矣。","py":[]},{"t":"此段當與第三節蟄伏藏氣穴同看。","py":[]},{"t":"玉液煉形法則","py":[]},{"t":"玉液煉形圖","py":[]},{"t":"初學之人，平素勞碌，乍入圜中，一旦安逸。逸則四肢不運動，安則百節不流通。以致脈絡壅塞，氣血凝滯，此通關蕩穢之法不能無也。","py":[]},{"t":"此法先用行氣主宰，照在玄膺一竅。此竅可通氣管，即黃庭經所謂，玄膺氣管受精符是也。少傾，則津液滿口，如井水然，微漱數遍，徐徐以意引下重樓，漸達膻中、尻尾、中脘、神闕，至氣海而止。就從氣海分開兩路，至左右大腿，從膝至三裏，下腳背及大拇指，又轉入湧泉，由腳跟腳彎循大腿而上至尾閭，合作一處，過腎堂、夾脊、雙關，分送兩肩、兩膀、兩臂至手背，由中指轉手掌，一齊旋迴過手腕，由胸旁曆腮後，從腦灌頂，複下明堂、上齶，以舌迎之，至玄膺而止。此為一轉畢。稍停又眼前行功，則壅滯之處漸次疏通，不唯貫穿諸經，亦能通達諸竅。即心印經所謂，七竅相通，竅竅光明是也。","py":[]},{"t":"蓋吾人靈明一竅，六合而內，六合而外，本無不周，本無不照，其不能然者，為形所礙耳。直要煉到形神俱妙，方纔與道合真。","py":[]},{"t":"夫行氣用眼者何也？故施肩吾曰：氣是添年藥，心為使氣神；若知行氣主，便是得仙人。昔人謂，目之所至，心亦至焉。心之所至，氣亦至焉。斯言確之矣。","py":[]},{"t":"煉形用液者何也？道家謂之蕩穢。玉液是津，玉池是口。黃庭內景雲：口為玉池太和官，漱咽靈液災不幹，體生光華炁香蘭，卻滅百邪玉鍊顏。審能修之登廣寒。蓋液中有氣，氣中有液，液氣相生，日充月盛，為金液之基，作潤身之寶。況能穿關透節，無處不到。古歌曰：華池神水頻吞嚥，紫府元君直上奔，常使氣通關節透，自然精滿穀神存。","py":[]},{"t":"夫玄膺一竅，乃是津液之海，生化之源，灌溉一身，皆本於此。故太上雲：舌下玄膺生死岸，子若遇之昇天漢。法華經頌雲：白玉齒邊流舍利，紅蓮香上放毫光，喉中甘露涓涓潤，心內醍醐滴滴涼。此乃小玉液煉形法也。","py":[]},{"t":"人之孔竅，所以通乎其虛，達乎其氣，而周流於一身之內焉，一或有所蔽塞，則為瘀痰、為壅血，而一身脈絡不能相通，便生疾病。今以此法日行三、五次，但得氣血流通，百脈和暢，病即去矣。止而勿行。此與退藏救護是為表裏，二段並行而不相悖。","py":[]},{"t":"夫涵養本原雖是去情識，實除生滅心。心無生滅，身無生滅定矣。欲除生滅心，必自無念始，無念之積習純熟，足可致無夢。無念之靜定純熟，足可致無生。無夢乃現在之大事也，無念乃末後之大事也。無生則不造，無夢則不化，不造不化，即不生不滅也。","py":[]},{"t":"夫學道之士，不患不成，唯患不勤。苟能專精而勤，未有學而不得也。設使立志不堅，信道不篤，朝為而夕改，始勤而中輟，悅於須臾，厭於持久，慾望與天齊壽，不亦難乎？","py":[]},{"t":"內觀經雲：知道易，信道難；信道易，行道難；行道易，得道難，得道易，守道難。若使不難，則滿市皆神仙矣。安足為異耶？","py":[]},{"t":"蓋修道者，如農夫之去草一般，務拔其根，則吾心天真種子自然發生矣。況此一字法門，徹首徹尾，甚易行，甚有驗。小而試之，可以卻病延年，大而用之，可以超凡入聖，在學者用功深淺何如耳。","py":[]}]},{"h":"亨集·安神祖竅翕聚先天","paras":[{"t":"安神祖竅翕聚先天","py":[]},{"t":"安神祖竅圖","py":[]},{"t":"（內附法輪自轉、龍虎交媾二法）","py":[]},{"t":"祖竅真際，舉世罕知，不得師傳，儼似暗中射垛。","py":[]},{"t":"蓋祖竅者，乃老子所謂玄牝之門也。悟真篇雲：要得穀神長不死，須憑玄牝立根基。所以紫陽言：修煉金丹，全在玄牝。於四百字序雲：玄牝一竅，而採取在此，交媾在此，烹煉在此，沐浴在此，溫養在此，結胎在此，至於脫胎神化，無不在此。修煉之士，誠能知此一竅，則金丹之道盡矣，所謂得一而萬事畢者是也。","py":[]},{"t":"然而丹經大都喻言，使學者無所歸著。前輩指為先天主人、萬象主宰、太極之蒂、混沌之根、至善之地、凝結之所、虛無之穀、造化之源、不二法門、甚深法界、歸根竅、複命關、中黃宮、希夷府、總持門、極樂國、虛空藏、西南鄉、戊己門、真一處、黃婆舍、守一壇、淨土、西方、黃中、正位、這個、神室、真土、黃庭，種種異名，難以悉舉。","py":[]},{"t":"然此一竅在身中求之，非口、非鼻、非心、非腎、非肝，非肺、非脾胃、非臍輪、非尾閭、非膀胱、非穀道、非兩腎中間一穴、非臍下一寸三分、非明堂泥丸、非關元氣海，然則果何處耶？","py":[]},{"t":"純陽祖師雲：玄牝玄牝真玄牝，不在心兮不在腎，窮取生身受氣初，莫怪天機都泄盡。且以生身之理言之，父母一念將媾之際，而圓陀陀、光燦燦，先天一點靈光撞於母胞，如此○而已。懦謂之仁，亦曰無極。釋謂之珠，亦曰圓明。道謂之丹，亦曰靈光。皆指此先天一氣、混元至精而言，實生身之原、受氣之初、性命之基、萬化之祖也。及父母交罷，精血包羅於外，如此◎而已，即吾儒所謂太極是也。由是而五臟，由是而六腑，由是而四肢，由是而百骸，由是而能視、能聽、能持、能行，由是而能仁、能義、能禮、能智，由是而能聖、能神、能文、能武，究竟生身本原，皆從太極中那一些兒發出來耳。","py":[]},{"t":"參同契雲：人所稟軀體，本一無。元精雲布，因炁託。初炁一疑定，玄牝立焉。上結靈關，下結氣海。靈關藏覺靈性，氣海藏生氣命。性命雖分龍虎二絃，而性命之根則總持於祖竅之內。","py":[]},{"t":"故老子曰：玄牝之門，是謂天地根。何以謂之玄牝之門而曰天地根也？豈非吾身之天地、吾身之玄牝耶？吾身天地之根、吾身玄牝之根耶？吾身玄牝之門、吾身天地之門耶？而天地之門之所從出者，獨不有所謂先天地生而為天地之根乎？故天地之根，乃天地之所由以分天而分地也，而玄牝之門之所從出者，獨不有所謂先玄牝生而為玄牝之根乎？故玄牝之根，乃玄牝之所由以分玄而分牝也。","py":[]},{"t":"何以謂之玄也？豈非從有名之母中發出來也？何以謂之玄之又玄？豈非從無名之始中發出來也？","py":[]},{"t":"無名之始，釋氏指為不二法門；子思曰其為物不二，則其生物不測；莊子曰昭昭生於冥冥，有倫生於無形。而欲悟性以見性者，其將求之昭昭而有倫乎？抑亦求之冥冥而無形乎？","py":[]},{"t":"冥冥無形，莫窺其朕。吾儒所謂無聲無臭，釋氏所謂威音王已前是也。然則何以謂之王，而其所以主張威音者，太極也，故謂之王。","py":[]},{"t":"餘於是而知學仙學佛者，但覓其王之所在而尊之爾，即尊王矣，而又且並其王而無有之，是遡太極而還於無極也。無極者，真中也。故曰聖聖相傳在此中，此中就是堯舜久執之中、孔子時中之中、子思未發之中、易之黃中通理之中、度人經之中理五炁之中，釋迦之空中之中，老子之守中之中。","py":[]},{"t":"然中字有二義。若曰中有定在者，在此中也。若曰中無定在者，乾坤合處乃眞中也。以其可得而久執也，故曰有定在。然豈特在此一身之內為然也？是雖一身之外，而遍滿天地，亦皆吾心之中也。又豈特在此天地之內為然也？是雖天地之外，而遍滿虛空，亦皆吾心之中也。","py":[]},{"t":"易曰：周流六虛。然周流於六虛之外，而非不足，退藏於一身之竅，而非有餘。故曰一竅能納太虛。空中道經雲：天之極上處距地之極下處，相去八萬四千裏。而天地之中，適當四萬二千里之中處也。若人身一小天地也，而心臍相去亦有八寸四分，而中心之中，適當四寸二分之中處也。此竅正在乾之下、坤之上、震之西、兌之東，八脈九竅、經絡聯輳、虛閑一穴，空懸黍珠，是人一身天地之正中，乃藏元始祖炁之竅也。","py":[]},{"t":"若知竅而不知妙，猶知中而不知一。昔人有言曰：心是地而性是王，竅是中而妙是一。一有數種，有道之一、有神之一、有氣之一、有水之一、有數之一、有一貫之一、有協一之一、有精一之一、有唯一之一、有守一之一、有歸一之一。歸一者，以其一而歸乎其中也。守一者，以其一而守乎其中也。有中則有一，一而非中，則非聖人之所謂一也。有一便有中，中而非一，則非聖人之所謂中也。故孔子之一，以其中之一而貫之也。堯舜之中，以其一之中而執之也。伏羲氏之河圖而虛其中者，先天也，乃吾身祖竅之中也。","py":[]},{"t":"孔子曰：先天而天，弗違。","py":[]},{"t":"老子曰：無名天地之始。","py":[]},{"t":"即釋氏所謂：茫乎，無朕一片，太虛是也。","py":[]},{"t":"神禹氏之洛書而實其中者，後天也，乃吾身祖竅之一也。","py":[]},{"t":"孔子曰：後天而奉天時。","py":[]},{"t":"老子曰：有名，萬物之母。","py":[]},{"t":"即道家所謂，露出端倪，一點靈光是也。","py":[]},{"t":"然而河圖中矣，中而未始不一。洛書一矣，一而未始不中。中包乎一，一主乎中，豈非精微之妙理、無為之神機耶？","py":[]},{"t":"道德經曰：多言數窮，不如守中。","py":[]},{"t":"洞玄經曰：丹書萬卷，不如守一。一者，生生不息之仁也。","py":[]},{"t":"中庸曰：修道以仁。","py":[]},{"t":"論語曰：天下歸仁。","py":[]},{"t":"禮記曰：中心安仁。","py":[]},{"t":"周易曰：安土敦仁。","py":[]},{"t":"予常譬之果實之仁，中有一點者，太極也。而抱之兩者，一陰一陽也。","py":[]},{"t":"易曰：易有太極，是生兩儀。故易也者，兩而化也。太極也者，一而神也。以此一點之神而含養於祖竅之中，不得勤，不得怠，謂之安神祖竅，非所以複吾身之乾元乎？以此一點之仁，而敦養於坤土之中，而勿忘，而勿助，謂之安土敦仁，非所以立吾身之太極乎？","py":[]},{"t":"又若蓮子之屬中，有一條而抱之兩片者，非所謂一以貫之邪？一而二、二而三、三生萬物。故張紫陽雲：道是虛無生一炁，便從一炁產陰陽，陰陽再合成三體，三體重生萬物昌。","py":[]},{"t":"昔文始先生問於老子曰：修身至妙至要，載於何章？老子曰：在於深根固蒂，守中抱一而已。","py":[]},{"t":"何謂守中？曰：勤守中，莫放逸，外不入，內不出，還本源，萬事畢。故老子所謂守中者，守此本體之中也。儒之執中者，執此本體之中。釋之空中者，本體之中，本洞然而空也。","py":[]},{"t":"老子所謂抱一者，抱此本體之一也。釋之歸一者，歸此本體之一也。儒之一貫者，以此本體之一而貫之也。","py":[]},{"t":"唯精唯一者，易之所謂精義入神者是也。久執厥中者，記之所謂王、中心、無為、以守至正者是也。曰王、中心者，蓋以一點之仁，主此中心之中，而命之曰王，所謂天君者是也。夫何為哉？以守至正而已矣。命由此立，性由此存，此兩者同出異名，原是竅中舊物。如今複返竅中，則蒙莊所謂南海之倏，北海之忽，相遇於混沌之地矣。","py":[]},{"t":"修丹之士，不明祖竅，則真息不住而神化無基，藥物不全而大丹不結。蓋此竅是總持之門、萬法之都，亦無邊傍，更無內外，不可以有心守，不可以無心求。以有心守之則著相。以無心求之則落空。若何可也？受師訣曰：空洞無涯是玄竅，知而不守是工夫。常將真我安止其中，如如不動、寂寂惺惺、內外兩忘、渾然無事，則神戀氣而凝，命戀性而住，不歸一而一自歸，不守中而中自守。中心之心既實，五行之心自虛，此老子抱一守中、虛心實腹之本旨也。","py":[]},{"t":"張紫陽雲：","py":[]},{"t":"虛心實腹義俱深，只為虛心要識心。","py":[]},{"t":"劉海蟾雲：","py":[]},{"t":"中央神室本虛閑，自有先天真氣到。","py":[]},{"t":"呂純陽雲：","py":[]},{"t":"守中絕學方知奧，抱一無言始見佳。","py":[]},{"t":"徐佐卿雲：","py":[]},{"t":"倏忽遨遊歸混沌，虎龍蟠距入中黃。","py":[]},{"t":"正陽翁雲：","py":[]},{"t":"要識金丹端的處，未生身處下功夫。","py":[]},{"t":"如如居士雲：","py":[]},{"t":"坤之上，乾之下，中間一寶難酬價。","py":[]},{"t":"李清庵中和集雲：","py":[]},{"t":"兩儀肇判分三極，乾以直專坤闢翕。天地中間玄牝門，其動愈出靜愈入。","py":[]},{"t":"王玉陽雲光集雲：","py":[]},{"t":"穀神從此立天根，上聖強名玄牝門。點破世人生死穴，真仙於此定乾坤。","py":[]},{"t":"譚處端水雲集雲：","py":[]},{"t":"陰居於上陽居下，陽氣先升陰氣隨。配合虎龍交媾處，此時如過小橋時。","py":[]},{"t":"河上公過明集雲：","py":[]},{"t":"杳杳冥冥開眾妙，恍恍惚惚葆真竅。斂之潛藏一粒中，放之彌漫六合表。","py":[]},{"t":"張紫陽悟真篇雲：","py":[]},{"t":"震龍汞自出離鄉，兌虎金生在坎方。二物總因兒產母，五行全要入中央。","py":[]},{"t":"張景和枕中記雲：","py":[]},{"t":"混元一竅是先天，內面虛無理自然。若向未生前見得，明知必是大羅仙。","py":[]},{"t":"葛仙翁玄玄歌雲：","py":[]},{"t":"乾坤合處乃真中，中在虛無甚空闊。簇將龍虎竅中藏，造化樞機歸掌握。","py":[]},{"t":"羅公遠弄九集雲：","py":[]},{"t":"一竅虛無天地中，纏綿祕密不通風。恍惚杳冥無色象，真人現在寶珠中。","py":[]},{"t":"天來子白虎歌雲：","py":[]},{"t":"玄牝之門鎮日開，中間一竅混靈臺。無關無鎖無人守，日月東西自往來。","py":[]},{"t":"張鴻蒙還元篇雲：","py":[]},{"t":"天地之根始玄牝，呼日吸月持把柄。隱顯俱空空不空，尋之不見呼之應。","py":[]},{"t":"高象先金丹歌雲：","py":[]},{"t":"其一之道何所云，莫若先敲戊己門。戊己門中有真水，真水便是黃芽根。","py":[]},{"t":"丁野鶴逍遙遊雲：","py":[]},{"t":"三教一元這個圈，生在無為象帝先。悟得此中真妙理，始知大道祖根源。","py":[]},{"t":"蕭紫虛大丹訣雲：","py":[]},{"t":"學人若要覓黃芽，兩處根源共一家。七返九還須識主，工夫毫髮不容差。","py":[]},{"t":"李靈陽祖竅歌雲：","py":[]},{"t":"個個無生無盡藏，人人本體本虛空。莫道瞿曇名極樂，孔顏樂亦在其中。","py":[]},{"t":"陳致虛轉語偈雲：","py":[]},{"t":"一者名為不二門，得門入去便安身。當年曾子一聲唯，誤了閻浮多少人。","py":[]},{"t":"薛紫賢虛中詩云：","py":[]},{"t":"天地之間猶橐籥，橐籥須知鼓者誰。動靜根宗由此得，君看放手有風無。","py":[]},{"t":"呂祖純陽文集雲：","py":[]},{"t":"陰陽二物隱中微，只為愚徒自不知。實實認為男女是，真真說做坎離非。","py":[]},{"t":"李道純無一歌雲：","py":[]},{"t":"道本虛無生太極，太極變而先有一。一分為二二生三，四象五行從此出。","py":[]},{"t":"壽涯禪師語錄雲：","py":[]},{"t":"陀羅門啟妙難窮，佛佛相傳只此中。不識西來真實義，空穿鐵履走西東。","py":[]},{"t":"馬丹陽醉中吟雲：","py":[]},{"t":"老子金丹釋氏珠，圓明無欠亦無餘。死戶生門宗此竅，此竅猶能納太虛。","py":[]},{"t":"曹文逸大道歌雲：","py":[]},{"t":"借問真人何處來，從前原只在靈臺。昔年雲霧深遮蔽，今日相逢道眼開。","py":[]},{"t":"劉長生仙藥集雲：","py":[]},{"t":"一竅虛空玄牝門，調停節候要常溫。仙人鼎內無他藥，雜礦銷成百煉金。","py":[]},{"t":"李道純中和集雲：","py":[]},{"t":"乾坤闔闢無休息，離坎升沉有合離。我為諸君明指出，念頭復處立丹基。","py":[]},{"t":"劉海蟾見道歌雲：","py":[]},{"t":"函谷關當天地中，往來日月自西東。試將寸管窺玄竅，虎踞龍蟠氣象雄。","py":[]},{"t":"無心昌老祕訣雲：","py":[]},{"t":"自曉穀神通此道，誰能理性慾修真。明明說向中黃路，霹靂聲中自得神。","py":[]},{"t":"玉蟾白真人云：","py":[]},{"t":"性之根，命之蒂，同出異名分兩類。合歸一處結成丹，還為元始先天炁。","py":[]},{"t":"緣督趙真人云：","py":[]},{"t":"虛無一竅正當中，無生無滅自無窮。昭昭靈靈相非相，杳杳冥冥空不空。","py":[]},{"t":"紫陽張真人金丹序雲：","py":[]},{"t":"此竅非凡竅，乾坤共合成。名為神氣穴，內有坎離精。","py":[]},{"t":"瑩蟾李真人道德頌雲：","py":[]},{"t":"闔闢應乾坤，斯為玄牝門。自從無出入，三界獨稱尊。","py":[]},{"t":"司馬子微雲：","py":[]},{"t":"虛無一竅號玄關，正在人身天地間。八萬四千分上下，九三六五列循環。大包法界渾無跡，細入塵埃不見顏。這個名為祖炁穴，黍珠一粒正中懸。","py":[]},{"t":"以上口訣，皆發明祖竅之妙。","py":[]},{"t":"老子曰：天地之間，其猶橐籥乎。","py":[]},{"t":"莊子曰：樞得其環中，以應無窮坤。","py":[]},{"t":"曰：正位居體鼎。","py":[]},{"t":"曰：正位凝命艮。","py":[]},{"t":"曰：君子思不出其位。","py":[]},{"t":"而孟子亦曰：立天下之正位，惟此正位也。以言乎其大，則足以包羅乎天地而無外。故謂之廣居而大道從此出矣。","py":[]},{"t":"毛詩曰：秉心塞淵。","py":[]},{"t":"太玄經曰：藏心於淵，美厥靈根。","py":[]},{"t":"參同契曰：真人潛深淵，浮游守規中。曰塞、曰藏，潛而守之之義也。然而浮游二字不可不知也。浮游者，優遊也。即孟子之所謂勿忘勿助也，釋氏所謂應如是住、如是降伏其心，亦此義也。","py":[]},{"t":"法輪自轉工夫","py":[]},{"t":"法輪自轉圖","py":[]},{"t":"三教法門，同途異轍，跡雖分三，理則一也。如此着工夫，釋家謂之法輪，道家謂之周天，儒家謂之行庭。","py":[]},{"t":"易曰：艮其背不獲其身，行其庭不見其人。無咎行庭者，天行健之之行也。天之行也，日一周天，何其健與。若吾身亦一小天地者，周天之行健也。","py":[]},{"t":"易曰：天行健，君子以自強不息。然吾身中之黃庭太極立焉，而天則旋乎其外而往來之不窮矣。艮曰時止則止，太極立焉。時行則行，周天行焉。","py":[]},{"t":"又不觀之系辭乎，系辭曰：日月相推而明生焉。又曰：寒暑相推而歲成焉。又曰：屈伸相感而利生焉。此行庭之心法也。","py":[]},{"t":"何為立極？即前所謂心中之仁安於中心之中而為土。中者，以敦養之，自有消息真機。而身心性命相為混合矣。","py":[]},{"t":"一屈一伸，一往一來，真有若日月之代明，寒暑之錯行，其殆天運之自然，是亦吾身之一天地也。","py":[]},{"t":"始而有意，終於無意。起初用意引氣旋轉由中而達外，由小而至大，口中默唸十二字訣曰：白虎隱於東方，青龍潛於酉位。一句一圈，數至三十六遍而止。及至收回，從外而旋內，從大而至小，亦念訣曰：青龍潛於酉位，白虎隱於東方。亦數三十六遍，複歸太極而止，是為一周天也。久則不必用意，自然璇璣不停，法輪自轉，真個有歇手不得處。","py":[]},{"t":"全陽子云：與日月而週迴，同天河而輪轉。輪轉無窮，壽命無極。","py":[]},{"t":"鳴道集雲：安閒自得長生道，晝夜無聲轉法輪。","py":[]},{"t":"韓逍遙雲：法輪要轉常須轉，只在身中人不見，駕動之時似日輪，日輪向我身中轉。","py":[]},{"t":"又云：法輪轉得莫停留，念念不離輪自轉。","py":[]},{"t":"當其轉也，滃然如雲霧之四塞，颯然如風雨之暴至，恍然如晝夢之初覺，渙然如沉屙之脫體。精神冥和，如夫婦之交接；骨肉融和，如澡浴之方起。","py":[]},{"t":"易曰：黃中通理，正位居體，美在其中，而暢於四肢。斯言信矣。","py":[]},{"t":"龍虎交媾法則","py":[]},{"t":"龍虎交媾圖","py":[]},{"t":"夫人也，坎離交則生，分則死，此理之必然，無一人不如此者。","py":[]},{"t":"蓋離三為陽，而居南，外陽而內陰也，謂之真汞。坎三為陰，而居北，外陰而內陽也，謂之真鉛。故紫陽真人云：日居離位反為女，坎配蟾宮卻是男。此言坎之男、離之女，猶父之精、母之血也；日之鳥、月之兔也；砂之汞、鉛之銀也；天之玄、地之黃也。此數者，皆指示龍虎二氣也。","py":[]},{"t":"參同契曰：離已日光，坎戊月精。故離之已象龍之弦氣也，坎之戊象虎之弦氣也。夫戊與己是黃庭真土之體，因太極一判，分居龍虎二體之中。修丹之士，若欲返其本，複其初，使龍虎歸於鼎中，情性歸於竅內，當用龍從火裏出、虎向水中生之二訣。則炎烈火中出飛龍之矯矯，泓澄水底躍走虎以耽耽，始得龍虎相交，向鴻蒙而潛歸混沌。繼則夫妻合體，從恍惚而竟入虛無、共至黃房，互相吞啖，兩情留戀，二氣交加，有如天地之媾精、日月之交光，盤旅於祖竅之間，自然複此先天未判之氣而成混元真一之精。為大藥之根原，作還丹之基本也。","py":[]},{"t":"原夫龍之情性常在於戊，虎之精性常在於已。只緣彼此各有土氣，二土合併而成刀圭，是以坎離交而地天泰，龍虎交而戊合己也。戊己合為一體，則四象會合而產大藥也。","py":[]},{"t":"易曰：天地氤氳，萬物化醇；男女媾精，萬物化生。天地以陰陽交媾而生物，丹法以陰陽交媾而生藥。蓋未有不交媾而用以成造化者也。","py":[]},{"t":"玉芝書雲：玄黃若也無交媾，爭得陽從坎下飛。是乃作丹之大端，修仙之第一義也。若天地之氣不氤氳，則甘露不降，坎離之體不災並，則黃芽不生。龍虎二絃之氣不會合，則真一種子不產。真一種子不產，則將何者為把柄而凝成金液大丹耶？","py":[]},{"t":"然交媾之理有二，有內交者，有外交者。坎離、龍虎交，內交也，產藥也。乾坤子午交，外交也，結丹也。此二法天淵不同，學者有細辨之。","py":[]},{"t":"張紫陽雲：既驅二物歸黃道，爭得金丹不解生。是此義也。","py":[]},{"t":"呂純職雲：二物會時為道本，五行全處得丹名。是此義也。","py":[]},{"t":"陳抱一雲：戊已乍交情性合，坎離才媾龍虎降。是此義也。","py":[]},{"t":"張用成雲：虎躍龍騰鳳浪粗，中央正位產玄珠。是此義也。","py":[]},{"t":"張平叔金丹四百字雲：龍從東海來，虎向西山起，兩獸戰一場，化作一泓水。亦此義也。","py":[]},{"t":"夫龍虎交媾者乃三元合一之法也，所以會乾坤、交坎離、簇陰陽、合性命，使二者複變而為一。以至九宮、八卦、七政、六位、五行，四象、三才之生於二者，莫不皆歸於二矣。一者，有物混成、先天地生是也。大哉！一乎！以其流行謂之炁，以其凝聚謂之精，以其妙用謂之神。","py":[]},{"t":"始因太極一判分居二體之中，日遠目疏，卒至危殆。是以聖人，則天地之要，知變化之源，取精於水府，召神於靈關。使歸玄牝竅中，得與祖炁聚會，三家相見，合為一體。先則凝神於混沌，次則寂照含虛空。抱一無離，是為返本還原之妙道也。","py":[]},{"t":"書曰：人心惟危，道心惟微，唯精惟一，允執厥中。蓋言心與精而為一，而會歸於黃中之中。而允執之者，此堯舜之所以開道統之傳，而為萬古聖學之宗也。","py":[]}]},{"h":"亨集·蟄藏氣穴眾妙歸根","paras":[{"t":"蟄藏氣穴眾妙歸根","py":[]},{"t":"蟄藏氣穴圖","py":[]},{"t":"（內附行、住、坐、臥四法）","py":[]},{"t":"前節言翕聚乃守中抱一之工夫，此節言蟄藏則深根固蒂之口訣。翕聚、蟄藏相為表裏，非翕聚則不能發散，非蟄藏亦不能發生，是此二節一貫而下，兩不相離者也。","py":[]},{"t":"此決無他，只是將祖竅中凝聚那點陽神下藏於氣穴之內，謂之送歸土釜，牢封固。又謂之凝神入氣穴。此穴有內外兩竅，外竅喻桃杏之核，內竅譬核中之仁。古仙有曰：混沌生前混沌圓，個中消息不容傳，劈開竅內竅中竅，踏破天中天外天。","py":[]},{"t":"此竅中之竅，釋尊標為空不空，如來藏。老君名之玄又玄。眾妙門海蟾亦曰無底，曰橐有孔，曰籥中間一竅。無人摸著，此指竅中之竅而言也。是竅也，為陰陽之源，神氣之宅，胎息之根，呼吸之祖。","py":[]},{"t":"胎者，藏神之府。息者，化胎之源。胎因息生，息因胎住。而竅中之竅，乃神仙長胎住息之真去處也。然天地之大辦一胎也。而日月之往來，斗柄之旋轉者，真息也。又不觀三氏之書乎？易經曰：成性存存，道義之門。道德經曰：玄之又玄，眾妙之門。遺教經曰：制之一處，無事不辨。皆直指我上真人呼吸處言之。","py":[]},{"t":"然則真人呼吸處果何處耶？吾昔聞之經曰：藏元精之窅冥府，結胎息之丹元宮，上赤下黑，左黑右白，中央黃暈之間，乃真人呼吸之處。正當臍輪之後，腎堂之前，黃庭之下，關元之上，即黃庭經所謂上有黃庭下關元，後有幽闕前命門是也。","py":[]},{"t":"廖蟾暉雲：前對臍輪後對腎，中間有個真金鼎是也。即識此處，即將向來所凝之神而安於竅中之竅，如龜之藏，如蛇之蟄，如蚌之含光，如蟾之納息，綿綿續續，勿忘勿助，若存而非存，若無而非無，引而收之。於無何鄉，運而藏之，於闔闢處少焉。呼吸相含，神氣相抱，結為丹母，鎮在下田。外則感召天地靈陽之正氣，內則擒制一身鉛汞之英華。如北辰所居，眾星皆拱。久則神氣歸根，性命合一，而大藥孕於其中也。","py":[]},{"t":"然凝神調息皆有口訣，不然恐思慮之神妄交於呼吸之氣，結成幻丹，而反害藥物矣。所以仙翁雲：調息要調真息息，煉神須煉不神神。","py":[]},{"t":"黃帝陰符經曰：人知其神之神，不知不神之所以神。不神者，性也。蓋性者，神之根也。神本於性，而性則未始神。神中炯炯而不昧者，乃是真性也。","py":[]},{"t":"仙姑大道歌曰：我為諸君說端的，命蒂從來在真息。真息者，命也。蓋命者，氣之蒂也。蒂本於命，而命則未始氣。氣中氤氳而不息者，乃是真命也。","py":[]},{"t":"這個不神之神，與那個真息之息，他兩個方纔是真夫妻、真陰陽、真龍虎、真性命。紐結做一團，混合為一處，打成作一片，煆煉在一爐，或名之曰牛女相逢、又曰牝牡相從、又曰烏免同穴、又曰日月同宮、又曰魂魄相投、又曰金火混融，究而言之，不過凝神合氣之法耳。","py":[]},{"t":"是以神不離氣，氣不離神，吾身之神氣合，而後吾身之性命見矣。性不離命，命不離性，吾身之性命合，而後吾身未始性之性、未始命之命見矣。崔公入藥鏡曰：是性命，非神氣，權而言之則二，實而言之則一。神氣固非二物，性命則當雙修。而雙修之旨，久失其傳，以至玄禪二門，五爭高下。","py":[]},{"t":"劉海蟾雲：真個佛法便是道，一個孩兒兩個抱。","py":[]},{"t":"清和翁曰：性命雙修教外傳，其中玄妙妙而玄。簇將元始歸無始，逆轉先天作後夭。","py":[]},{"t":"此端奧妙，非師罔通，口訣玄微，詳載於後。今姑就諸仙所證者而言之，便於初機而易得悟入也。","py":[]},{"t":"按白玉蟾雲：昔日遇師親口訣，只要凝神入氣穴。氣穴者，內竅也。蟄神於中，藏氣於內，以如來空空之心，合真人深深之息，則心息相依，息調心淨。蓋蘊一點真心於炁中，便是凝神入氣穴之法。神既凝定氣穴，常要回光內照。照顧不離，則自然旋轉，真息一降一升，而水火木金相為進退矣。","py":[]},{"t":"仙諺曰：欲得長生，先須久視。久視於上丹田，則神長生；久視於中丹田，則氣長生；久視於下丹田，則形長生。","py":[]},{"t":"夫日月之照於天地間，蚌吸之則生珠，頑石蓄之則產玉，何況人身自有日月，豈不能回光內照，結自己之珍珠。產自已之美玉哉？","py":[]},{"t":"然而神即火也，氣即水也。水多則火滅，火多則水幹。中年之人，大抵水不勝火者多矣。所以，命宜早接，油要早添。添油之法已載前教護命寶之下。今複進言，則天人一氣之旨盡露矣。","py":[]},{"t":"夫天人之際，唯一氣之相為闔闢，相為聯屬已爾，而非有二也。故我而呼也，則天地之氣於焉，而發而散。我而吸也，則天地之氣於焉，而翕而聚。此天人相與之微，一氣之感通者然也。故天地所以能長且久者，以其呼吸於其內也。人能效天地呼吸於其內，亦可與天地同其長久。","py":[]},{"t":"曹仙姑雲：元和內運即成真，呼吸外施終未了。以口鼻之氣往來者，外呼吸也。乾坤之氣闔闢者，內呼吸也。","py":[]},{"t":"蕭了真雲：老子明開眾妙門，一開一闔應乾坤。果於罔象無形處，有個長生不死相。此指內呼吸也。","py":[]},{"t":"張平叔雲：玄牝之門世罕知，休將口鼻妄施為。饒君吐納經千載，爭得金烏搦兔兒。此斥外呼吸也。","py":[]},{"t":"外呼吸乃色身上事，接濟後天以養形體。內呼吸以法身上事，栽培先天以養穀神。","py":[]},{"t":"蓋內呼吸之息，原從天命中來，非同類之物不能相親。是以聖人用伏炁之法，奪先天地之沖和，逆上雙關。前返乎後，以達本根。使母之氣伏子之氣，子母眷戀於其間，則息息歸根，而為金丹之母矣。","py":[]},{"t":"前輩雲：伏炁不服氣，服氣須伏炁。服氣不長生，長生須伏炁。炁之積於下者，無地可透，自然升之而上至髓海。積於上者，無處可奔。自然降之而下至海氣。二氣相接，迴圈無端。古先達人得濟長生者，良由有此逆用之法也。","py":[]},{"t":"此法自始至終丟他不得。起手時有救護補益之功；第二節有流戊就己之功；第三節有添油接命之功；第四節有助火載金之功；第五節火熾而有接濟之功；第六節胎成而有沐浴之功；第七節溫養而有乳哺之功。嬰兒救出於苦海，此時到岸不須船，這著功夫才無用矣。","py":[]},{"t":"且人始生也，一剪肚臍而幾希性命即落在我之真人呼吸處矣；既之而在於天地之間；又既之而在於肉團之心；又既之而散於耳目口鼻四肢百骸。日復一日，神馳氣散，乃死之途也。","py":[]},{"t":"故神仙以歸伏法度人，必先教之返本。返本者何？以其散之於耳目口鼻四肢百骸者而複返於肉團之心，謂之涵養本原。又將以肉團心之所涵養者而複返之於天地之間，謂之安神祖竅。又將以天地間之所翕聚者而複返之於真人呼吸處，謂之蟄藏氣穴。日復一日，神凝氣聚，乃生之途也。","py":[]},{"t":"古仙曰：屋破修容易，藥枯生不難。但知歸伏法，金寶積如山。此時補完乾體，接續氣數，以全親之所生，以全天之所賦，真汞纔有八兩，真鉛始足半斤，若嬰兒心同赤子，陰陽吻合，混沌不分，出息微微，入息綿綿，漸漸入而漸漸柔，漸漸和而漸漸定，久則竅中動息兀然自住，內氣不出，外氣反進，此是胎息還元之初，眾妙歸根之始也。","py":[]},{"t":"呂知常曰：一息暫停，方可奪天地造化。","py":[]},{"t":"程伊川曰：若非竊造化之機，安能長生？","py":[]},{"t":"翁葆光曰：一刻之工夫，可在天地一年之氣數。","py":[]},{"t":"此三老者豈虛語哉？益胎息妙凝之時，入無積聚，出無分散，體相虛空，泯然入定。定久，內外合一，動靜俱無，璿機停輪，日月合壁，萬裏陰沉春氣合，九霄清澈露華凝。妙矣哉！其陰陽交感之真景象於斯時也。元精吐華，而乾金出礦矣。此係重開混沌，再入胞胎，開無漏花，結菩提果，非夙有仙骨者，不能知此道之妙也。","py":[]},{"t":"後有密戶前生門，出日入月呼吸存。此老氏黃庭外景經之口訣也。","py":[]},{"t":"只就真人呼吸處，放教奼女往來飛。此李長源混元寶章之口訣也。","py":[]},{"t":"內交真炁存呼吸，自然造化返童顏。此許旌陽醉思仙歌之口訣也。","py":[]},{"t":"西方金母最堅剛，走入壬家水裏藏。此石杏林還元篇中之口訣也。","py":[]},{"t":"要知大道希夷理，太陽移在月明中。此薛紫賢複命篇中之口決也。","py":[]},{"t":"先賢明露丹臺旨，幾度靈鳥宿桂柯。此劉海蟾還金篇中之口訣也。","py":[]},{"t":"兩般靈物天然和，些子神機這裏求。此陳默然崇正篇中之口訣也。","py":[]},{"t":"古佛之音超動靜，真人之息自遊絲。此釋鑒源青蓮經中之口訣也。","py":[]},{"t":"一息漸隨無念窅，半醒微覺有身浮。此羅念庵胎息篇中之口訣也。","py":[]},{"t":"出息不隨萬緣，人息不居蘊界。此般若尊者答東印度國王口訣也。","py":[]},{"t":"水銀實滿葫蘆裏，封固其口置深水。此萼綠華氣穴圖中之口訣也。","py":[]},{"t":"萬物生皆死，元神死複生。以神歸氣穴，丹道自然成。此石杏林之口訣也。","py":[]},{"t":"歸根自有歸根竅，複命寧無複命關。踏破兩重消息子，超凡入聖譬如閑。此李清庵之口訣也。","py":[]},{"t":"心思妙，意思玄，臍間元氣結成丹。穀神不死因胎息，長生門戶要綿綿。此羣仙珠玉口訣也。","py":[]},{"t":"專氣致榮神久留，往來真息自悠悠。綿綿迤邐歸元命，不汲靈泉常自流。此海蟾翁口訣也。","py":[]},{"t":"一條直路少人尋，風虎雲龍自嘯吟。坐定更知行氣主，真人之息又深深。此陳致虛口訣也。","py":[]},{"t":"圓不圓來方不方，森羅天地暗包藏。如今內外兩層白，體在中央一點黃。此大成集口訣也。","py":[]},{"t":"息調心淨守黃庭，一部渾全圓覺經。悟劫此身猶是幻，蒲團坐上要惺惺。此抱樸子口訣也。","py":[]},{"t":"經營鄞鄂體虛無，便把元神裏面居。息往息來無間斷，聖胎成就合元初。此陳虛白口訣也。","py":[]},{"t":"諦觀三教聖人書，息之一字最簡直。若於息上做功夫，為佛為仙不勞力。思緣達本禪之機，息心明理儒之極，息氣凝神道之玄。三息相須無不克。此李道純中和集中之口訣也。","py":[]},{"t":"胎息訣","py":[]},{"t":"袁天綱胎息訣","py":[]},{"t":"夫元氣者，大道之根，天地之母，一陰一陽，生育萬物。在人為呼吸之氣，在天為寒暑之氣。能改移四時之氣者，戊己也。","py":[]},{"t":"春在巽，能發生萬物。夏在坤，能長養萬物。秋在乾，能成熟萬物。冬在艮，能含養萬物。","py":[]},{"t":"故學道者，當取四時正氣，納人胎中，是為真種，積久自得，心定，神定，息定，龍親虎會，結就聖胎，謂之真人胎息。太始民胎息訣","py":[]},{"t":"夫道，太虛而已矣。天地、日月皆從太虛中來。故天地者，太虛之真胎也。日月者，太虛之真息也。","py":[]},{"t":"人能與太虛同體，則天地即我之胎，日月即我之息，太虛之包羅即我之包羅。豈非所謂超出天地、日月之外而為混虛。氏其入歟。","py":[]},{"t":"達摩祖師胎息經","py":[]},{"t":"胎從伏氣中結，氣從有胎中息。氣入身中為之生，神去離形為之死。知神氣可以長生。固守虛無以養神氣。神行則氣行，神住而氣住。若欲長生，神氣相注，心不動念，無來無去，不出不入，自然常住。勤而行之，是真道路。","py":[]},{"t":"張景和胎息訣","py":[]},{"t":"真玄真牝，自呼自吸，似春沼魚，如百蟲蟄，灝氣融融，靈風習習，不濁不清，非口非鼻，無去無來，無出無入，返本還原，是真胎息。","py":[]},{"t":"王子喬胎息訣","py":[]},{"t":"奉道之土，須審子午卯酉四時，乃是陰陽出入之門戶。定心不動，謂之曰禪。神通萬遍，謂之曰靈。智周萬事，謂之曰慧。道元合炁，謂之曰修。真炁歸元，謂之曰煉。龍虎相交，謂之曰丹。三丹同契。謂之曰了。","py":[]},{"t":"有志於道者，知此根源，依法修行，自可入於長生大道矣。","py":[]},{"t":"許棲嚴胎息訣","py":[]},{"t":"凡修道者，常行內觀，遺去三屍，驅除六賊，納氣於丹田，定心於覺海。心定則神寧，神定則氣住，氣住則胎長矣。胎之長者，由於息之住地，無息不胎，無胎不息，住息長胎，聖母神孩。故曰：胎息定而金木交，心意甯而龍虎會也。","py":[]},{"t":"王方平胎息訣","py":[]},{"t":"凡所修行，先定心炁。心炁定則神凝，神凝則心安，心安則氣升，氣升則境忘，境忘則清靜，清靜則無物，無物則命全，命全則道生，道生則絕相，絕相則覺明，覺明則神通。","py":[]},{"t":"經曰：心通萬法皆通，心靜方法皆滅。此我佛如來真定法門者也。學者果能定心氣，凝胎息，則還丹不遠，金液非遙。","py":[]},{"t":"赤松子胎息訣","py":[]},{"t":"氣穴之問，昔人名之為生門死戶，又謂之天地之根。凝神於此，久之，元氣日充，元神日旺。神旺則氣暢，氣暢則血融，血融則骨強，骨強則髓滿，髓滿則腹盈，腹盈則下實，下實則行步輕健，動作不疲，四肢康健，顏色如桃，去仙不遠矣。","py":[]},{"t":"性空子胎息訣","py":[]},{"t":"我之本體本自圓明，圓明者是我身中天地之真胎也。我之本體本自空寂。空寂者，是我身中日月之息也。唯吾身之天地有真胎矣，而後天地之胎與我之胎相為混合而胎我之胎，唯吾身之日月有真息矣。而後日月之息與我之息相為混合而息我之息，唯吾身之本體既虛空矣。而後虛空之虛空與我之虛空相為混合而虛空我之虛空。","py":[]},{"t":"幻真先生胎息銘","py":[]},{"t":"三十六，一咽為先，吐唯細細，納唯綿綿，坐臥亦爾，行立坦然，戒於喧雜，忌以腥羶，假名胎息，實曰內丹，非只治病，決定延年，久久行之，名列上仙。","py":[]},{"t":"以上口訣，舉其大略，餘者載於丹經，不可得而盡述。此蟄藏工夫其用大矣。謂人之元神，藏於氣穴，猶萬物藏於坤土。神入也，中天氣降而至於地氣，與神合，猶地道之承於天。","py":[]},{"t":"參同契曰：恆順地理，承天布宣。","py":[]},{"t":"易曰：至哉！萬物資生。","py":[]},{"t":"蓋亥月純坤用事之時，時當草木歸根，蟄蟲入戶，閉塞成冬，冬雖主藏，然次年發育之功實胚胎於此。","py":[]},{"t":"蓋一陽不生於複而生於坤，坤雖至陰，然陰裏含陽，大藥之生實根只於此。藥將產時，就與孕婦懷胎相似，保完真種，不敢放肆。慎起居，節飲食，忌酒色，戒惱怒。外不役其形骸，內不勞其心志。至於行、住、坐、臥，各各有方，行則措足於坦途，住則凝神於太虛，坐則調丹田之息，臥則抱臍下之珠。故曰行、住、坐、臥不離這個。","py":[]},{"t":"行禪圖、立禪圖","py":[]},{"t":"坐禪圖","py":[]},{"t":"臥禪圖","py":[]},{"t":"坐不必跌跏，當如常坐。夫坐雖與常人同，而能持孔門心法則與常人異矣。所謂孔門心法者，只要存心在真去處是也。","py":[]},{"t":"蓋耳目之竅，吾身之門也。方寸之地，吾身之堂也。立命之竅，吾身之室也。故眾人心處於方寸之地，猶人之處於堂也，則聲色得以從門而搖其中。至人心藏於立命之竅，猶人之處於室也，則聲色無所從入而窺其際，故善事心者，潛室以頤晦而耳目為虛矣。禦堂以聽政，而耳目為用矣。若坐時不持孔門心法，便是坐馳，便是放心。","py":[]},{"t":"壇經曰：心念不起名為坐，自性不動名為禪坐，禪妙義端不外此。","py":[]},{"t":"古人有言，修道易，煉魔難，誠哉是言也。然色魔、食魔易於制伏，獨有睡魔難煉，是以禪家有長坐不臥之法。蓋人之真元常在夜間走失，苟睡眠不謹，則精自下漏，氣從上泄，元神無依亦棄軀而出，三寶各自驅散，人身安得而久存哉？","py":[]},{"t":"至人睡時，收神下藏丹窟，與氣合交，水火互相拘鈐，則神不外馳而氣自安定矣。","py":[]},{"t":"今以常人言之，神則寄於目矣。而夜寐既熟，則藏之於腎，至夙興之時，而目之神有不爽然清乎？藉其不夜而腎神豈能清？","py":[]},{"t":"今又以天道言之，日則麗之於天矣，而夜淪地中則藏之於海，至啟明之侯，而天之氣有不爽然乎？藉其不夜而海氣豈能清？","py":[]},{"t":"此則崔公入藥鏡所謂水火交，永不老是也。","py":[]},{"t":"今之人懵而睡，忽然而醒，是何物主之而使之覺也？夫魂與神並則覺，魄與屍合則昏。昏者，死之根。覺者，生之兆。魂屬陽而喜清虛，魄屬陰而好馳騁。魄者，鬼也。魂者，神也。","py":[]},{"t":"神則日接之於物，夜形之於夢。黃粱未熟，南柯未寤，一生之榮辱富貴，百歲之悲憂悅樂，備嘗於一夢之間。使其去而不還遊，而不返則生死路隔，幽冥之途絕矣。","py":[]},{"t":"由是觀之，人不能自生而其所以生者，夢中之人為之也，不能自死而其所以死者，夢中之人為之也。然不知所以夢，則亦不知所以死，不知所以覺，則亦不知所以生。夢中之有覺者，以夢之中而自有真覺者在焉。死中之有生者，以死之中而自有長生者在焉。是故，因覺知生，因夢知死，知斯二者，可以入道矣。","py":[]},{"t":"夫人之覺也，耳其有不能聽乎，目其有不能視乎，手其有不能持乎，足其有不能行乎，心其有不能喜、不能怒乎。而人之睡也，耳固在也，何其不能聽乎？目固在也，何其不能視乎？手固在也，何其不能持乎？足固在也，何其不能行乎？心固在也，何其不能喜、不能怒乎？由此觀之，則其死也，似為無知而無覺矣。","py":[]},{"t":"而人之睡而夢也，而夢之時，亦有耳能聽矣，而其聽也，何其不屬於人之耳乎？亦有目能視矣，而其視也，何其不屬於人之目乎？亦有用能持矣，而其持也，何其不屬於人之手乎？亦有足能行矣，而其行也，何其不屬於人之足乎？亦有心能喜、能怒矣，而其喜也、怒也，何其不屬於人之心乎？由此觀之，則其死也，似為有知而有覺矣。","py":[]},{"t":"然死生通乎晝夜之道、夢覺之常者乎？古之真人，其覺也，無憂；其寐也，無夢。故無夢地位，非道成之後不能到也。然初機之士，煉心未純，昏多覺少，才一閤眼，元神離腔，睡魔入舍，以致魂夢紛飛，無所不至，不惟神出氣移，恐有漏爐迸鼎之患。","py":[]},{"t":"若欲敵此睡魔，須用五龍盤體之法。訣曰：東首而寢，側身而臥，如龍之蟠，如犬之曲，一手曲肱枕頭，一手直摩臍腹，一隻腳伸，一隻腳縮，未睡心，先睡目，致虛極，守靜篤，神氣自然歸根，呼吸自然含育，不調息而息自調，不伏氣而氣自伏。依此修行，七祖有福。陳希夷己留形於華山，蔣青霞曾脫殼於王屋。此乃臥禪的旨，與那導引之法不同。功夫到時，自然寢寐神相抱，覺悟候存亡，亦能遠離顛倒夢想。即漆園公所謂，古之真人，其覺也，無憂；其寢也，無夢是矣。","py":[]},{"t":"然雖睡熟，常要惺惺，及至醒來，慢慢輾轉，此時心地湛然，良知自在，如佛境界。正白樂天所云：前後際斷處，一念未生時，此際若放大，靜一場效驗。真有不可形容著。昔尹師靜室中有一聯雲：覺悟時切不可妄想，則心便虛明。紛擾中亦只如處常，則事自順遂。","py":[]},{"t":"李真人滿江紅詞雲：好睡家風，別有個睡眠三昧。但睡裏心誠，睡中澄意，睡法既能知旨趣，便於睡裏調神氣。這睡功，消息睡，安禪少人會。","py":[]},{"t":"又敵魔詩云：坐中昏睡怎禁它，鬼面神頭見也麼。昏散皆因由氣濁，念緣未斷屬陰多。漸來水面侵堤岸，風定江心絕浪波。性寂情空心不動，坐無昏散睡無魔。","py":[]},{"t":"上古之人，有息無睡。故曰：嚮晦入晏，息若一覺。睡熟陽光盡為陰濁所陷，就如死人一般，若知晏息之法，當嚮晦時。耳無聞，目無見，口無言，心無累，鼻息無喘，四肢無動。那一點元神真氣相依相戀，如爐中種火相似。久久純熟，自然神滿不思睡，氣滿不思食，精滿不思欲，元炁自聚，真精自凝，胎嬰自棲，三屍向滅，九蟲自出，所謂睡魔不知從何而去矣。其身自覺安而輕，其心自覺虛而靈，其氣自覺和而清，其神自覺圓而明。若此便入長生路，休問道之成不成。","py":[]},{"t":"紫中道人答問","py":[]},{"t":"客問：坐禪一事如何？","py":[]},{"t":"予答曰：咽津納氣，是人行有藥，方能坐化生鼎內。若無真種子，猶將熱火煮空鐺。釋氏雲：此是守屍鬼魔磚作鏡的工夫。其言相是而不相非，粵自晉之伯陽、宋之紫陽，絕唱斯道，厥後纘其緒也，即海瓊、紫瓊、黃房、緣督、上陽諸真疊繼，則金丹之草一絲之脈，至今不斷，代不乏人，以接紹三教一源之道統。若言守靜兀坐，乃最下小乘之法，外道惑人之邪徑耳。","py":[]},{"t":"客複問：然則畢竟如何？","py":[]},{"t":"予曰：子肯大施法財，告天萌願，即當為汝言。","py":[]},{"t":"客跽而請曰：弟子曆劫難遇，今生遭逢，原師慈悲，恩莫大焉乎。","py":[]},{"t":"曰：子來，吾語汝。子今信誓旦旦，予將妄言之，子勿妄聽之；予以實言之，子勿妄信之，當告汝言。夫精、氣、神三寶，則撐持宇宙，總括陰陽。天地得之而含蓋乾坤，人心得之則修仙做佛。唯有內有外，知之者可以兼而修之，不知者獨修一物。獨修者，乃頑冥之漢也；兼修者，能證仙佛之果也。緣其亂統，則說到此地，未有不望洋而退舍者矣乎。果無疑，當以告子，凡言內外兼修者，其精在遝冥恍惚之中。此精姓金，喚九三郎，諱元晶，號曰金華商夫君，居玉池之西，出入跨虎，乳名嬰兒，晚則喚為金公。凡到鄰家，便稱主人，其情嗜交梨。此乃先天地之精，卻為人之至寶。其炁乃虛無中來，此炁姓白，喚太乙郎，名元炁，號曰：宇宙主宰素練郎君。寄居西川，出入騎白虎，乳名喚真種子，晚則呼白頭老子。到鄰家，便稱父母，好食烏龜而多情。此為先天地之真炁，即是人之至寶。","py":[]},{"t":"故上陽子曰：既自虛無中來，卻非天之所降，地之所出，又非我身所有，亦非精、亦非血、非草木、非金石，是皆非也。誰得而知之乎？然以先天地之神而言，其神號無位真人，佛雲紇利陀耶。佛若認得此神，卻有妙用。此神專主殺人、專主生人。修仙作佛者，必要此神主之，方得。而內經故曰：人身中殆有兩精者，一魂一魄是也。夫隨精往來者，神即是也。白祖雲：唯人，頭有九宮，中一宮名曰穀神。神常居其穀，日則接於物，夜則接於夢，神不能安其居也。南柯未斷，黃粱未熟，一生之榮辱富貴，百歲之優悲悅樂，備嘗於一夢之間，使之遊而不返，去而不還，則幽冥之途、隔生死之路絕矣。由是觀之，人不能自生而神生之，人不能自死而神死之。若神長居其谷，人烏得而死乎？紫陽曰：煉神須煉不神神。蓋謂此耳。天穎子曰：雖久學定身，心無五時七候者，促齡穢質，色謝歸空。自雲：慧覺複，稱道成，實所失。然可謂謬矣。","py":[]},{"t":"若言坐禪之士，予所厭聞，故上古聖仙之貴，當於人類中修之，如或未然，乞勿開口，未當醒悟。","py":[]}]},{"h":"利集·天人合發採藥歸壺","paras":[{"t":"天人合發採藥歸壺","py":[]},{"t":"採藥歸壺圖","py":[]},{"t":"（內附閉任開督，聚火載金二訣）","py":[]},{"t":"聞之師曰：人受天地中氣以生原有真種，可以生生無窮，可以不生不滅，但人不能保守，日日消耗，卒至於亡。間知保守，又不知鍛煉火法，終不堅固，易為造化所奪。苟能保守無虧，又能以火鍛煉，至於凝結成丹，如金如玉，可以長生，可以不化。","py":[]},{"t":"蓋欲煉此丹，雖以藥物為主，欲採藥物，當在根本用功。何謂根本，吾身中太極是也。","py":[]},{"t":"天地以混混沌沌為太極，吾身以窈窈冥冥為太極。天地以此陰陽交媾而生萬物，吾身以此陰陽交媾而生大藥。大藥之生於身，與天地生物不異，總只是陰陽二氣。二施一化而玄黃相交，一稟一受而上下相接，混而為一。故曰：混沌。混沌，乃天地之郛郭窈冥，亦是大藥之胞胎也。","py":[]},{"t":"南華經雲：至道之精，窈窈冥冥。","py":[]},{"t":"道德經雲：窈兮冥兮，其中有精。","py":[]},{"t":"其精甚真，唯此真精，乃吾身中之真種子是也。以其入於混沌，故名太極，以其為一身造化之始，故名先天，以其陰陽未分，故名一氣；又名黃芽；又名玄珠；又名真鉛；又名陽精。","py":[]},{"t":"此精若凝結於天地之間。或為金，或為石，曆千百年而不朽。人能反身而求之，於自己陽精凝結成寶，則與天地相，為無窮金石。奚足比哉。","py":[]},{"t":"然此陽精不容易得。蓋人之一身徹上徹下，凡屬有形者，無非陰邪渣濁之物。故雲房真人曰：四大一身皆屬陰，不知何物是陽精。","py":[]},{"t":"緣督子曰：一點陽精，祕在形山，不在心腎，而在乎玄關一竅。","py":[]},{"t":"趙中一曰：一身內外盡皆陰，莫把陽精裏面尋。","py":[]},{"t":"丘長春曰：陽中雖是房中得之，而非禦女之術。內非父母所生之軀，外非山林所產之寶。但著在形體上摸索皆不是，亦不可離形體而向外尋求。","py":[]},{"t":"若此等語何異水中撈月，鏡裏攀花，真正智過顏閔，實難強猜，是以祖師罕言之，而世人罕知之。不獨今之為然，然古人亦有難知之語。","py":[]},{"t":"如玉鼎真人云：五行四象坎和離，詩談分明說與伊。藥生下手功夫處，幾人會得幾人知。","py":[]},{"t":"紫陽真人云：此個事，世間稀，豈是等閒人得知？","py":[]},{"t":"杏林真人云：神氣歸根處，身心複命時，這些真孔竅，料得少人知。","py":[]},{"t":"伯陽真人云：一者，以掩蔽世人莫知之。一者何物也，就是那末發之中，不二之一，即前所謂先天一氣是也。","py":[]},{"t":"翠虛篇雲：大藥須憑神氣精，採來一處結交成。丹頭只是先天氣，煉作黃芽發玉英。","py":[]},{"t":"複命篇雲：採二儀未判之氣，奪龍虎始媾之精。閃入黃房，煆成至寶。","py":[]},{"t":"崇正篇雲：寒淵萬丈睡驪龍，頷下藏珠炯炯紅。謹密不驚方採得，更依時日法神功。","py":[]},{"t":"蓋採者，以不採而採之，取者以不取而取之，在於靜定中有非動作可為也。昔黃帝遺其玄珠，使知索，使離珠索，使喫詬索，索之皆不得，乃使罔象，罔象得之。罔象者，忘形之謂也。必忘形罔象，然後先天一氣可得。","py":[]},{"t":"擊琅集先天吟雲：一片先天號太虛，當其無事見真腴。","py":[]},{"t":"又云：若問先天一字無，後天方要著工夫。","py":[]},{"t":"何謂先天？寂然不動，窈窈冥冥，太極未判之時是也。何謂後天？感而遂通，恍恍惚惚，太極已判之時是也。","py":[]},{"t":"混元寶章雲：寂然不動感而通，窺見陰陽造化功。信乎，寂然不動，則心與天通而造化可奪也。","py":[]},{"t":"翠虛篇雲：莫向腎中求造化，卻煩心裏覓先天。","py":[]},{"t":"當其喜怒未發之時，睹聞不及之地，河海默然，山嶽藏煙，日月停景，璿璣不行，八脈歸源，呼吸俱泯，既深入於窈冥之中，竟不知天之為蓋，地之為輿，亦不知世之有人，己之有軀。少焉，三宮氣滿，機動簌鳴，則一劍鑿開混沌，兩手擘裂鴻蒙，是謂無中生有。","py":[]},{"t":"甯玄子詩云：不在塵勞不在山，直須求到穹冥端。何謂穹冥端？虛極靜篤之時也。心中無物為虛，念頭不起為靜。致虛而至於極，守靜而至於篤，陰陽自然交媾。陰陽一交，而陽精產矣。","py":[]},{"t":"故陳圖南曰：留得陽精，神仙現成。蓋陽梢日日發生，但世人不知翕聚，以致錯而為周身之氣。至人以法追攝，聚而結一黍之珠。釋氏呼為菩提，仙家名曰真種。修性者若不識這個善提子，即圓覺經所謂種性外道是也。修命者若不識這個真種子，即玉華經所謂枯坐旁門是也。","py":[]},{"t":"張紫陽曰：大道修之有易難也，知由我，也由天。人若不知藥生，不知採取，不知烹煉，但見其難，不見其易。誠知藥生時候，採取口訣，烹煉功夫，但見其易，不見其難。此兩者在人遇師與不遇師耳。故曰：月之圓存乎口訣，時之子妙在心傳。然時之子，卻有兩說，有個活子時，有個正子時。","py":[]},{"t":"昔聞尹師曰：欲求大藥為丹本，須認身中活子時。","py":[]},{"t":"又偈雲：","py":[]},{"t":"因讀金丹序，方知玄牝竅。因讀入藥鏡，只知意所到。","py":[]},{"t":"大道有陰陽，陰陽隨動靜。靜則入窈冥，動則恍惚應。","py":[]},{"t":"真土分戊己，戊已不同時。已到但自然，成到有作為。","py":[]},{"t":"烹煉坎中鉛，配合離中汞。鉛汞結丹砂，身心方入定。","py":[]},{"t":"曰動靜，曰窈冥，曰真土，皆是發明活子時之口訣也雲。","py":[]},{"t":"何謂之動靜？曰寂然不動，返本複靜坤之時也，吾則靜以待之。靜極而動，陽氣潛萌複之時也，菩則動以應之。當動而或雜之以靜，當靜而或間之以動，或助長於其先，或忘失於其後，則皆非動靜之常矣。","py":[]},{"t":"夫古之至人，其動也，天行其靜也。淵默當動則動，當靜則靜，自有常法。今之學者，不知丹法之動靜有常。或專主乎動，或專主乎靜。其所謂動者，乃行氣之動；其所謂靜者，乃禪定之靜。二者胥失之矣。","py":[]},{"t":"指玄篇不云乎：人人氣血本通流，榮衛陰陽百刻周，豈在閉門學行氣，正如頭上又安頭。曷嘗以行氣為動哉。","py":[]},{"t":"翠虛篇不云乎：唯此乾坤真運用，不必兀兀徒無言，無心無念頭已昏，安得凝聚成胎仙？豈以禪定為靜哉。","py":[]},{"t":"凡人動極而靜，自然入於窈冥。竊冥即是寐時，雖入於無天、無地、無我、無人境界，卻不涉於夢境。若一涉夢境，即有喜怒、驚恐、煩惱、悲歡、愛欲種種情況，與晝間無異，且與穹冥時無天、無地、無人、無我景絕不相似。似窈窈冥冥，唯晝間動極思靜，有此景象，若夜間睡熟，必生夢境。安得有此？晝間每有窈冥時候，人多以紛華念慮害之而求其時入窈冥者，蓋亦鮮矣。","py":[]},{"t":"崔公入藥鏡雲：一日內，十二時，意所到，皆可為。一日之內，意到不止一次，來藥亦不止一次。張平叔所謂一粒複一粒，從微而至著是也。","py":[]},{"t":"大抵藥物，當以真意求之，故曰：好把真鉛著意尋。又日：恆向華池著意尋。蓋人身真意，是為真土。真土之生有時，不由感觸，自然發生，雖與中馬上一切喧鬧之地不能禁止，故曰真土。具土有二，戊已是也。土既有二，則意亦有二必矣。所謂二者，一陽一陰是也。謂之真者，無一毫強偽，若有一毫強與偽，即是用心揆度謀慮，便屬虛假，非真意也。","py":[]},{"t":"有此真意，真鉛方生。何謂有此真意？真鉛方生？蓋動極而靜，真意一到，則人窈冥，此意屬陰，是謂己土。陰陽交媾，正當一陽爻動之時，自覺心花發現，暖氣沖融，陰陽年交，真精自生，真精即是真鉛，所謂水鄉鉛，只一味是也。","py":[]},{"t":"陰陽交媾，將判未判，恍恍惚惚，乃是靜極而動，此意屬陽，是為戊土。此時真鉛微露，藥苗新嫩，此乃有物有象之時，與平旦幾希一般。撥動關戶，急忙用功採取，則窈冥所生真精方無走失。","py":[]},{"t":"所謂採取功夫，即達摩祖師形解訣，海蟾祖初乘訣。二訣大略相同，不外乎吸舐撮閉四宇。純陽祖師雲：窈窈冥冥生恍惚，恍恍惚惚結成團。正是此訣。雖則是有為之法，然非真土，一生何以施功？是非採鉛。由於真土生也，故曰真土擒真鉛。鉛升與汞配合，汞得鉛自不飛走，故曰真鉛制真汞。鉛汞既即真土，則身心自爾寂然不動，而金丹大藥結矣。","py":[]},{"t":"是以一時之內，自有一陽來複之機。是機也，不在冬至，不在朔旦，亦不在子時，非深達天地陰陽、而曉身中造化者，莫如活子時如是其祕也。既曰一日十二時，凡相媾處皆可為，而古仙必用半夜子陽初動之時者，何也？其時太陽正在北方，而人身氣到尾閭關，蓋與天地相應，乃可以盜天地之機，奪陰陽之妙，煉魂魄而為一，合性命而雙修。唯此時乃坤複之間，天地開闢於此時，日月合壁於此時，草木萌孽於此時，人身之陰陽交會於此時，神仙於此時而採藥，則內真外應，若合符節，乃天人合發之機，至妙至妙者也。","py":[]},{"t":"陳泥丸雲：每當天地交合時，盜取陰陽造化機。","py":[]},{"t":"陰符經雲；食其時，百骸埋；盜其機，萬化安。何者謂之機？天根理極，微今年初盡處時，日起頭時，此際易得，意其間難下詞。人能知此意，何事不能知？此際正是造化真機妙處。盡真機之妙者，周易也。盡周易之妙者，複卦也。盡複卦之妙者，初爻也。故曰複其見天地之心乎？","py":[]},{"t":"蓋此時，天地一陽來複，而吾身之天地亦然，內以採取吾身之陽，外以盜取天地之陽，則天地之陽有不悉歸於我之身中而為我之藥物乎？然而天地雖大，造化雖妙，亦不能越此發機之外矣，此感彼應理之自然。","py":[]},{"t":"人若知此天人合發之機，遂於中夜靜坐，凝神聚氣，收視返聽，閉塞其兌，築固靈株，一念不生，萬緣頓息。渾渾淪淪，如太極之未分；溟溟沁沁，如兩儀之未兆。湛兮！獨存如清淵之印月，寂然不動；如止水之無波，內不覺，其一身外不知其宇宙。夫亥之末，子之初，天地之陽氣至則急採之，未至則虛以待之，不敢為之先也。","py":[]},{"t":"屈原遠遊篇雲；","py":[]},{"t":"道可受兮，不可傳。","py":[]},{"t":"其小無外兮，其大無限。母滑而魂兮，彼將自然。","py":[]},{"t":"一氣孔神兮，於中夜存。虛以待之兮，無為之先。","py":[]},{"t":"許旌陽三藥歌雲：存心絕慮候晶凝。","py":[]},{"t":"指玄篇雲：塞兌垂簾默默窺。皆是藏器待時之謂也。嗚呼！時辰若至不勞心，內自相交自結凝。八室按時須等著，一輪曦馭自騰升。豈可為之先也哉。","py":[]},{"t":"夫金丹大藥，孕於先天，產於後天，其妙在乎太極將判未判之間。靜已極而未至於動，陽將複而未離乎陰。斯時也，冥冥兮，如煙嵐之罩山，濛濛兮，如霧氣之籠水，霏霏兮，如冬雪之漸凝漸聚；沉沉兮，如漿水之漸碇漸清。俄頃，癢生毫竅，肢體如綿，心覺恍惚，而陽物勃然舉矣。此時陽氣通天，信至則瓊鐘一扣，玉洞雙開，時至氣化，藥產神知，地雷震動巽門開，龍向東潭踴躍來。此時玄關透露而精金出礦之時矣。","py":[]},{"t":"邵康節雲：恍惚陰陽初變化，氤氳天地三迴旋。中間些子好光景，安得功夫入語言。","py":[]},{"t":"白玉蟾雲：因看斗柄運周天，頓悟神仙妙訣。一點真陽生坎位，補卻離宮之缺。自古神仙，這些離坎日日無休歇。今年冬至，梅花依舊凝雪。","py":[]},{"t":"先聖此日閉關，不通來往，皆為羣生設物。物總含生育意，正在子初亥末，造物無聲，水中火起，妙在虛危穴。如今識破，金鳥飛人蟾窟。所謂虛危穴者，即地戶禁門是也。其穴在於任督二脈中間，上通天谷，下達湧泉。故先聖有言：天門當開，地戶永閉。蓋精氣聚散常在此處，水火發端也在此處，陰陽變化也在此處，有無入也在此處，子母分胎也在此處。","py":[]},{"t":"翠虛篇雲：有一子母分胎路，妙在尾箕鬥牛女。此穴千涉最大，系人生死岸頭，故仙家名為生死窟。","py":[]},{"t":"參同契雲：築固靈採者此也，拘束禁門者此也。","py":[]},{"t":"黃庭經雲：閉塞命門保玉都者，此也，閉了精路可長活者此也。","py":[]},{"t":"益真陽初生之時，形如烈火，狀似炎風，斬關透路而出，必由此穴經過。因閉塞緊密，攻擊不開，只得驅回尾閭，連空焰起人天衢，望上奔，一撞三關，直透頂門，得與真汞配合，結成丹砂。非拘束禁門之功而誰歟。","py":[]},{"t":"呂組純陽文集中之口訣：","py":[]},{"t":"無中出有還丹象，陰裏生陽大道基。","py":[]},{"t":"李清庵火候歌之口訣：","py":[]},{"t":"極致清虛守靜篤，靜中一動陽來複。","py":[]},{"t":"鐘離權破迷正道歌口訣：","py":[]},{"t":"一點最初真種子，入得丹田萬古春。","py":[]},{"t":"白玉蟾方法歸一歌口訣：","py":[]},{"t":"一陽方動大丹成，片晌工夫造化靈。","py":[]},{"t":"瑩蟾子煉虛歌口訣：","py":[]},{"t":"虛極只虛元氣凝，靜之又靜陽來複。","py":[]},{"t":"劉海蟾還金篇口訣：","py":[]},{"t":"渺邈但撈水裏月，分明只採鏡中花。","py":[]},{"t":"許旌陽石涵篇記口訣：","py":[]},{"t":"恍惚穹冥二氣精，能生萬象合乾坤。","py":[]},{"t":"張紫陽悟真篇口訣：","py":[]},{"t":"恍惚之中尋有象，穹冥之內覓真精。","py":[]},{"t":"還陽子見性篇口訣：","py":[]},{"t":"日精若與月華合，自有真鉛出世來。","py":[]},{"t":"張用成悟真篇口訣：","py":[]},{"t":"若問其鉛何物是，蟾光終日照西川。","py":[]},{"t":"諸真玄奧廣集口訣：","py":[]},{"t":"真鉛不產五金內，生在穹冥天地先。","py":[]},{"t":"李道純原道歌口訣：","py":[]},{"t":"坎水中間一點真，急須取向離中輳。","py":[]},{"t":"李清庵中和集口訣：","py":[]},{"t":"三物混融三性合，一陽來複一陰消。","py":[]},{"t":"劉奉真白龍洞中之口訣：","py":[]},{"t":"些兒須問天根處，亥子中間得最真。","py":[]},{"t":"梅志仙採藥歌口訣：","py":[]},{"t":"陰蹺泥丸，一氣迴圈。下穿地戶，上撥天關。","py":[]},{"t":"石杏林口訣：","py":[]},{"t":"萬籟風初起，千山月三圓。急須行政生，便可運周天。","py":[]},{"t":"瑩蟾子口訣：","py":[]},{"t":"可道非常道，行動是外功。些兒真造化，恍惚穹冥中。","py":[]},{"t":"石得之口訣：","py":[]},{"t":"藥取失天氣，火尋太陽精。能知藥取火，定裏見丹成。","py":[]},{"t":"呂純陽口訣：","py":[]},{"t":"要覓長生路，除非認本元。都來一味藥，剛道數千般。","py":[]},{"t":"金碧經口訣：","py":[]},{"t":"元君始煉汞，神室含洞虛。玄白生金公，巍巍建始初。","py":[]},{"t":"彭鶴林口訣：","py":[]},{"t":"得訣歸來試煉看，龍爭虎戰片時間。九華天上人知得，一夜風雷撼萬山。","py":[]},{"t":"上陽子口訣：","py":[]},{"t":"虎之為物最難言，尋得歸來玄又玄。一陽初動癸生處，此際因名大際先。","py":[]},{"t":"陳泥丸口訣：","py":[]},{"t":"半斤真汞半斤鉛，隱在靈源太極先。須趁子時當採取，煉成金液入丹田。","py":[]},{"t":"呂純陽口訣：","py":[]},{"t":"捉得金精固定基，日魂東畔月華西。於中煉就長生藥，服了還同天地齊。","py":[]},{"t":"徐神翁口訣：","py":[]},{"t":"燦燦金華日月精，溶溶玉液乾坤髓。夜深天宇間無塵，唯有蟾光照神水。","py":[]},{"t":"陳默然口訣：","py":[]},{"t":"兌金萬寶正西成，桂魄中秋倍樣明。便好用功施採取，虛中以待一陽生。","py":[]},{"t":"玄奧集口訣：","py":[]},{"t":"一泓神水滿華池，夜夜池邊白雪飛。雪裏有人擒玉兔，趕教明月上寒枝。","py":[]},{"t":"陳圖南口訣：","py":[]},{"t":"窈冥才露一端倪，恍惚未曾分彼此。中間主宰這些兒，便是世人真種子。","py":[]},{"t":"陳翠虛口訣：","py":[]},{"t":"只取一味水中金，收拾虛無造化窟。促將百脈盡歸根，脈住氣停丹始結。","py":[]},{"t":"龍盲子口訣：","py":[]},{"t":"先天一氣號其鉛，莫信迷徒妄指傳。南北滋張緣朕兆，一靈飛走賴拘鈐。","py":[]},{"t":"鐘離權口訣：","py":[]},{"t":"塞兌垂簾寂默窺，滿空白雪亂參差。殷勤收拾無令失，貯看孤輪月上時。","py":[]},{"t":"薛道光口訣：","py":[]},{"t":"無不為之有以為，坎中有白要歸離。水源初到極清處，一點靈光人不知。","py":[]},{"t":"呂洞賓口訣；","py":[]},{"t":"奠怪瑤池消息稀，只緣人事隔天機。若人尋得水中火，有一黃童上太微。","py":[]},{"t":"瑩蟾子李翁口訣：","py":[]},{"t":"玄關欲透作工夫，妙在一陽來複。天癸方生忙下手，採處切須虔篤。","py":[]},{"t":"邵康節口訣：","py":[]},{"t":"忽然夜半一聲雷，萬戶千門次第開。若識無中含有象，許君親見伏羲來。","py":[]},{"t":"上陽子口訣：","py":[]},{"t":"元來一味坎中金，未得師傳枉用心。忽爾打開多寶藏，木非土也不成林。","py":[]},{"t":"陳翠虛口訣：","py":[]},{"t":"父精母血結胎成，尚自他形似我形。身內認吾真父母，方纔捉得五行精。","py":[]},{"t":"陳泥丸口訣：","py":[]},{"t":"西南路上月華明，大藥還從此處生。記得古人詩一句，曲江之上鵲橋橫。","py":[]},{"t":"玄奧集中口訣：","py":[]},{"t":"煉丹仔細辨功夫，晝夜殷勤在藥爐。若遇一陽才起複，覺時須採老時枯。","py":[]},{"t":"張三峯口訣：","py":[]},{"t":"佛印指出虛而覺，丹陽訣破無中有。捉住元初那點真，萬古千秋身不朽。","py":[]},{"t":"珠玉集中口訣：","py":[]},{"t":"水鄉鉛，只一味，不是精神不是氣。元來即是性命根，隱在先天心坎內。","py":[]},{"t":"上陽子口訣：","py":[]},{"t":"恰恰相當絕妙奇，中秋天上月圓時。陽生急採無今緩，進火功夫要慮危。","py":[]},{"t":"陳泥丸口訣：","py":[]},{"t":"寓坎名為水火精，本是乾坤二卦成。但取坎宮點離穴，純乾便可攝飛瓊。","py":[]},{"t":"玄奧集口訣：","py":[]},{"t":"憂惚之中有至精，龍吟虎嘯最堪聽。玄珠飛趁昆侖去，晝夜河車不暫停。","py":[]},{"t":"薛紫賢口訣：","py":[]},{"t":"軋軋相從響發時，不從他得豁然知。桔槔說盡無生曲，井底泥蛇舞柘枝。","py":[]},{"t":"許宜平口訣：","py":[]},{"t":"返本還原已到乾，能升能降號飛仙。一陽生是興功日，九轉周為得道年。","py":[]},{"t":"陳翠虛口訣：","py":[]},{"t":"日烏月兔兩輪圓，根在先天採取難。月在望中能採取，天魂地魄結靈丹。","py":[]},{"t":"金丹撮要口訣：","py":[]},{"t":"一氣團成五物真，五物團成一物靈。奪得乾坤真種子，子生孫兮又生孫。","py":[]},{"t":"回穀子口訣：","py":[]},{"t":"精神氣血歸三要，南北東西其一家。天地變通飛白雪，陰陽和合產金華。","py":[]},{"t":"王果齋口訣：","py":[]},{"t":"精神氣，藥最親，以此修丹尚未真。修丹只要乾坤髓，乾坤髓即坎離仁。","py":[]},{"t":"陳泥丸口訣：","py":[]},{"t":"鉛汞相傳世所稀，硃砂為質雪為衣。朦朧只在君家舍，日日君看君不知。","py":[]},{"t":"李清庵口訣：","py":[]},{"t":"先天至理妙難窮，鉛產西方汞產東。水火二途分上下，玄關一竅在當中。","py":[]},{"t":"王陽明口訣：","py":[]},{"t":"閑觀物態皆生意，靜悟天機入穹冥。道在險夷隨地樂，心忘魚鳥自流行。","py":[]},{"t":"邵康書口訣：","py":[]},{"t":"天心複處是無心，心到無時無處尋。若謂無心便無事，水中何故卻生金。","py":[]},{"t":"李清庵中和集中之口訣：","py":[]},{"t":"煉汞烹鉛本沒時，學人當向定中推。客塵欲染心無著，天癸才生神自知。","py":[]},{"t":"性寂金來歸性本，精凝坎去補南離。兩般靈物交並後，陰盡陽純道可期。","py":[]},{"t":"李道純中和集中之口訣：","py":[]},{"t":"火將容易藥非遙，天癸生如大海潮。兩種汞鉛知採取，一齊物慾盡捐消。","py":[]},{"t":"掀翻萬有三元合，煉盡諸陰五氣朝。十月脫胎丹道畢，嬰兒形兆渴神霄。","py":[]},{"t":"陳楠口訣：","py":[]},{"t":"奪取天機妙，夜半看辰杓，一些殊露。阿誰運列稻花頭，便向此中採取。","py":[]},{"t":"宛如碧蓮含蕊，滴破玉池秋萬籟。風初起，明月一沙歐。","py":[]},{"t":"以上皆諸真得藥口義，各引數言，以便印證者。","py":[]},{"t":"聚火載金訣法","py":[]},{"t":"聚火載金圖","py":[]},{"t":"起先運南方離宮之火，以煉北方水中之金，是為以紅投黑，則凝神入坤臍而生藥。如今運北方水中之金，以制南方火中之木，是為以黑見紅，則凝神入乾頂而成丹。","py":[]},{"t":"故紫陽悟真篇雲：","py":[]},{"t":"依他坤位生成體，種在乾家交感宮。","py":[]},{"t":"崔公入藥鏡雲：產在坤，種在乾。乾居上為鼎，坤居下為爐。非猛烹極煆則藥不能出爐，非倒行逆旋則藥不能升鼎。鉛者，其性沉重之物也，若不得火，何由而飛？汞者，其性飛揚之物也，若不得鉛，何由而結？是以聚火之法最為緊要也。","py":[]},{"t":"何謂聚火之法？此法即達摩、海蟾二祖師吸、舐，撮、閉四字訣是也。吸者，鼻中吸氣以接先天也。舐者，舌拄上齶以迎甘露也。撮者，緊攝穀道內中提，明月輝輝頂上飛也。閉者，塞兌垂簾兼逆聽，久而神水落黃庭也。","py":[]},{"t":"胡翠湖雲：下不閉則火不聚而金不升，上不閉則藥不凝而丹不結。是以聚火之法，乃採取烹煉之先務也。其恍恍惚惚是採取時候，猛烹極煉是採取功夫，吸、舐、撮、閉又是烹煉之的旨也。","py":[]},{"t":"夫採取之法，貴乎知時，不可太早，太早則藥嫩易升。亦不可太遲，太遲則藥老成質。必鉛華吐白，玄珠成象，方是採取時節。","py":[]},{"t":"張紫陽雲：鉛遇癸生須急採，金逢望遠不堪嘗。","py":[]},{"t":"張三豐雲：電光煉處尋真種，風信來時覓本宗。","py":[]},{"t":"電光煉處，則穹冥之後，恍惚之間，一陽爻動之時，珠落畢池之際。此時節用參同契拘束禁門訣，緊塞太玄，閉任開督。即忙鼓之以橐籥，吹之以巽風，煆之以猛火。火熾則水沸，水沸則駕動河車，載金上升，泥丸與真汞配合，汞得鉛降，亦不飛走。如此漸漸抽添，漸漸凝結，自然鉛日減，汞日添。久之鉛盡汞自乾，陰盡陽自純，至此則金丹大藥成矣。","py":[]},{"t":"煉此大藥，別無他術，只是採取先天一點祖炁，以為金丹之母耳。受之師曰：煉大梵之祖炁，飛時後之金晶，存帝一之妙相，返三素於黃庭。此是口訣中之口訣也。","py":[]},{"t":"學者徒知以鉛汞交結為丹，而不知採取、抽添、烹煉、火候各有次序法度。蓋採取以作其始，抽添以成其終，於中調停，全仗火候。","py":[]},{"t":"所以紫陽雲：","py":[]},{"t":"縱識硃砂及黑鉛，不知火候也如閑。","py":[]},{"t":"朱晦翁雲：","py":[]},{"t":"神仙不作參同契，火候工夫哪得知。","py":[]},{"t":"薛道光雲：","py":[]},{"t":"聖人傳藥不傳火，從來火候少人知。莫將大道為兒戲，須其神仙仔細推。","py":[]},{"t":"火候之法，有文有武，不可一律齊也。靜中陽動，金離礦地，下雷轟，火逼金。此第四節之火候也。謾守藥爐看火候，但安神息任天然。此第六節之火候也。陽文陰武無令失，進退抽添有馭持。此第五節之火候也。成性存存者，儒家之火候也。綿綿若存者，道家之火候也。不得勤、不得怠者，釋家之火候也。三月不違者，顏子之火候也。吾日三省者，曾子之火候也。日知其所亡，月無忘其所能者，夏之火候也。戒慎乎，其所不睹；恐懼乎，其所不聞，子思之火候也。必有事焉而無正心，勿忘而勿助長者，孟子之火候也。發憤忘食，孔子之武火也。樂以忘憂，孔子之文火也。不知老之將至雲爾者，至誠無息而火候純也。火候純，大丹成，而作聖之功畢也。","py":[]}]},{"h":"利集·乾坤交媾去礦留金","paras":[{"t":"乾坤交媾去礦留金","py":[]},{"t":"乾坤交媾圖","py":[]},{"t":"（內附卯酉周天口訣）","py":[]},{"t":"予前以性命之統乎其中者而言之，乃上乘法也。予今以性命之歸乎其根者而言之，乃最上乘法也。","py":[]},{"t":"夫以性命之統乎其中者，此道寥寥，自鐘呂而下世鮮知矣。況乎性命之歸乎其根者耶，而世之知之者為尤鮮矣。似此竅妙之奧、性命之微，若不復語重言，則學者難於悟入。","py":[]},{"t":"原人自父母之生以前，本體太虛而已矣。其餘之所謂無極者乎？既而父母媾精，而後一點靈光而已矣。其餘之所謂太極者乎？而一點靈光，原從太極中來者，我之元神也。由是而氣，由是而形，唯知有此形氣已爾。美衣美食以奉養此身也，功名富貴以尊崇此身也。如此而生，如此而死，自以為得矣。而子思之所謂天命之性者，非唯不能知，亦且不願知也。而其所以不願知者，豈非孟子所謂不可以已而失其本心者乎？","py":[]},{"t":"若能知所以，反而求之，以複還我太虛一炁之本初，一點靈光之舊物者，非此金丹大道不可也。","py":[]},{"t":"然而金丹大道之祕密在性命兩字。性者，天也，常潛於鼎，故頂者，性之根也。命者，海也，常潛於臍，故臍者，命之帶也。經雲：性在天邊，命在海底是也。","py":[]},{"t":"蓋天中之竅圓而藏性，能通於地中之竅。故其貫也則自上而下，直養而無害也。地中之竅方而藏命，能通於天中之竅，故其貫也則自下而上，直養而無害也。","py":[]},{"t":"孔子曰：智者，動天圓之象也。仁者，靜地方之象也。天圓者何？圓陀之義也。乃性之所寄，為命之根矣。地方者何？方寸之義也。乃命之所繫，為性之根也。性命混成，實非有兩，潛天而天，潛地而地，優優洋洋，無體無方。在眼日見，在耳日聞，在鼻辨香，在口談論，在手執捉，在足運奔。悟者知是佛性，迷者喚作精魂。","py":[]},{"t":"蓋怫性者，本性也。而所謂本性者，豈非是我本來之所自有之真性歟。真性者，天命之性也。以其不落邊際，故謂之中。以其一直無妄，故謂之誠。以其與物同體，故謂之仁。以其至尊無對，故謂之獨。混淪一個，無欠無餘。及乎太極一判，兩儀始分，則輕清者騰而在上，重濁者碇而在下。於是坎宮有鉛，離官有汞，而向之所謂一物分為二，能知二者名。","py":[]},{"t":"這二者之名，丹經不敢漏泄，巧喻多端，萬字千名，不可勝計。如論頂中之性者，喻之曰汞也、龍也、火也、根也、日也、魂也、離也、乾也、己也、天也、君也、虛也、兔也、無也、主也、浮也、硃砂也、扶桑也、奼女也、昆侖也；如論臍中之命者，喻之曰鉛也、虎也、水也、蒂也、月也、魄也、坎也、坤也、戊也、地也、臣也、實也、烏也、有也、賓也、沉也、水銀也、華嶽也、嬰兒也、曲江也。至於陰中含陽，陽中藏陰，千言萬論，不過引喻二者之名耳。","py":[]},{"t":"故元皇訣曰：鉛汞鼎中居，煉成無價珠。都來兩個字，了盡萬家書。","py":[]},{"t":"鐘離翁曰：除卻汞鉛兩味藥，其他都是誑愚迷。","py":[]},{"t":"高象先曰：夢謁西華到九天，真人授我指玄篇。其中簡易無多子，只要教人煉汞鉛。","py":[]},{"t":"馬丹陽曰：鉛汞是水火，水火是龍虎，龍虎是神氣，神氣是性命。","py":[]},{"t":"總來只是這兩個字，兩個字只是一個理。故盲修者岐而二之，若真修者合而一之。合一者，煉炁而凝神，盡性而至命，烹鉛而幹汞，取坎而填離。","py":[]},{"t":"蓋離中靈物號曰流珠，寓神則營營而亂，寓精則持盈而難保。所以葛仙翁作流珠歌歎其難馭而易失也。豈不觀魏伯陽云乎：太陽流珠，常欲去人，卒得金華，轉而相因。又曰：河上奼女，靈而最神，將欲制之，黃芽為根。曰金華，曰黃芽，皆指真鉛而言，真鉛者，乃太陰之精也。曰流珠，曰奼女，皆指靈汞而言，靈汞者，太陽之氣也。","py":[]},{"t":"然此靈汞，其唯猛烈，見火則飛走無蹤，不得真鉛，何以制伏？故紫陽曰：要者須制伏覓金公。金公者，鉛字也。蓋鉛自曲江而來，穿夾脊、徹玉京，斡旋沂流直上泥丸。雖名抽鉛添汞，實是還精補腦。","py":[]},{"t":"翠虛篇雲：","py":[]},{"t":"天有七星地七寶，人有七竅權歸腦。","py":[]},{"t":"太古集雲：","py":[]},{"t":"金丹運至泥丸穴，名姓先將記玉都。","py":[]},{"t":"法寶遺珠雲：","py":[]},{"t":"識得本來真面目，始知生死在泥丸。","py":[]},{"t":"黃庭經雲：","py":[]},{"t":"泥丸百節皆有神。","py":[]},{"t":"又云：","py":[]},{"t":"腦神精根字泥丸。","py":[]},{"t":"又云：","py":[]},{"t":"一面之神宗泥丸，泥丸九真皆有房。方圓一寸處此中，但思一部壽無窮。","py":[]},{"t":"所謂方圓一寸者，即釋迦摩頂受記之處也。此處乃玄中之玄，天中之天。鬱羅蕭臺，玉山上京。腦血之瓊房，魂精之玉室，百靈之命宅，津液之山源。此正在兩耳交通之穴，前明堂後，玉枕上，華蓋下，絳宮北極太淵之中，乃真一元神所居之室也。","py":[]},{"t":"昔黃帝上峨嵋山，見天真皇人於玉堂，請問真一之道。皇人曰：此道家之至重其經，上帝祕在昆侖五城之內。藏以玉函，刻以金紮，封以紫泥，印以中章。吾聞之精雲：在北極太淵之中，前有明堂，後有玉枕。上有華蓋，下有絳宮。巍巍華蓋，金樓穹窿。左罡右魁，激波揚空。紫芝被崖，朱草朦朧。白玉嵯峨，日月垂光。曆火過水，經玄涉黃。城門交錯，帷帳琳琅。龍虎烈衛，神人在旁。不施不與，一安其所。不遲不疾，一安其室。能暇能預，一乃不去。守一存真，一乃通神。少欲約食，一乃留息。白刃臨頭，思一得生。知一不難，難在於終。守之不失，可以無窮。此真一祕旨之略也。","py":[]},{"t":"故道德經曰：天得一以清，地得一以寧，神得一以靈，穀得一以盈，萬物得一以生，王侯得—以為天下。貞所謂神以知來，知以藏往也。所謂大而化之之謂聖，聖而不可知之之謂神也。分之為二，陰陽之根底也。分之為五，五行之樞紐也。又分為八，八八六十四而為河圖之數也。又分為九，九九八十一而為洛書之數也。又散之為萬，生生化化萬物之綱維也。","py":[]},{"t":"羲文得其一，而周易興焉；禹箕得其一，而洪範疇焉；周茂叔得其一，而太極圖焉；邵堯夫得其一，而經世作焉；老子得其一，而萬事畢焉；釋迦得其一，而萬法歸焉。歸根者，歸此也。複命者，複此也。","py":[]},{"t":"西升經曰：人能守一，一亦守人。思一至饑，一與之糧。思一至渴，一與之漿。","py":[]},{"t":"靈樞經曰：天穀元神，守之自真。","py":[]},{"t":"又曰：子欲長生，抱一當明。","py":[]},{"t":"又曰：抱一守真，神自通靈。","py":[]},{"t":"人能握神守一於本宮，則真炁自升、真息自定、真精自朝、靈苗自長、天門自開、元神自現。頂竅開而竅竅齊開，元神居而神神聽命。神既居其竅而不散，則人安得而死乎？即黃庭經所謂，子欲不死，修昆侖是也。","py":[]},{"t":"故丘處機雲：","py":[]},{"t":"久視昆侖守真一，守得摩尼圓又赤。清虛浩曠陀羅門，萬佛千仙從此出。","py":[]},{"t":"還元篇雲：","py":[]},{"t":"悟道顯然明廓落，閑閑端坐運天關。","py":[]},{"t":"此是根本功夫，頭腦學間，撥天關之手段，脫死籍之靈章。此道上蒼所祕，古今仙佛皆不敢明言。真所謂千人萬人中一人兩人知者也。玄哉！玄哉！更有言不盡的口訣。","py":[]},{"t":"再一叮嚀，當其真鉛入鼎之時，須要驅除雜念，奮速精神，口視頂門，用志不分，霎時龍虎交戰，造化爭弛，雷轟電掣，撼動乾坤，百脈悚然，九宮透徹，金晶灌頂，銀浪沖天。","py":[]},{"t":"紫陽所謂：以黑而變紅，一鼎雲氣濃。少頃玉鼎湯溫，金爐火散，黃芽遍地，白雪漫天，夫唱妻隨，龍吟虎嘯，陰戀陽魂，陽抱陰魄，鉛精汞髓，凝結如珠。","py":[]},{"t":"玉蟾所謂：夫婦老相逢，恩情自留戀，此際玄珠成，象礦去金存。而一點金液複落於黃庭舊處矣。","py":[]},{"t":"斯時也，溶溶然如山雲之騰太虛，霏霏然似膏雨之遍原野，淫淫然若春雨之滿澤，液液然像河水之將釋。百脈衝和而暢乎四體，真個是拍拍滿懷都是春也。見此效驗，急行卯酉周天，進陽火，退陰符，使東西會合，南北混融，則四象五行攢族一鼎，混有靈於天穀，理五氣於泥丸也。","py":[]},{"t":"高象先雲：","py":[]},{"t":"玄珠飛到昆侖上，子若求之憑罔象。","py":[]},{"t":"河東歌雲：","py":[]},{"t":"兩物擒來共一爐，一泓神水結真酥。","py":[]},{"t":"指玄篇雲：","py":[]},{"t":"必知會合東西路，切在沖和上下田。","py":[]},{"t":"陳泥丸雲：","py":[]},{"t":"白虎自茲相見後，流珠哪肯不相從。","py":[]},{"t":"段真人云：","py":[]},{"t":"四象五行攢族處，乾坤日月自然歸。","py":[]},{"t":"漸悟集雲：","py":[]},{"t":"因燒丹藥火焰下，故使黃河水逆流。","py":[]},{"t":"純粹吟雲：","py":[]},{"t":"子午爐前分進退，乾坤鼎內列浮沉。","py":[]},{"t":"玄奧集雲：","py":[]},{"t":"金消木性相交合，黑汞結鉛自感通。","py":[]},{"t":"雲房真人云：","py":[]},{"t":"驅回斗柄玄關理，斡轉天關萬象通。片響龍虎頻鬥罷，二物相交頃刻中。","py":[]},{"t":"指玄篇雲：","py":[]},{"t":"奔歸氣海名朱驥，飛入泥丸是白鴉。昨夜虎龍爭戰罷，雪中微見月鉤斜。","py":[]},{"t":"醒眼詩云：","py":[]},{"t":"木金間隔各西東，雲起龍吟虎嘯風。二物寥寥天地回，幸因戊己會雌雄。","py":[]},{"t":"陳泥丸雲：","py":[]},{"t":"子時氣到尾閭關，夾脊河東透甑山。一顆水晶入爐內，赤龍舍汞上泥丸。","py":[]},{"t":"翠虛篇雲：","py":[]},{"t":"醉倒酣眠夢熟時，滿船載寶進曹溪。一方識破丹基後，放去收來總是伊。","py":[]},{"t":"古仙歌雲：","py":[]},{"t":"水銀一味是仙藥，從上傳流伏火難。若遇河東成紫粉，粉霜一吐化金丹。","py":[]},{"t":"玄奧集雲：","py":[]},{"t":"移將北斗過南辰，兩手雙擎日月輪。飛赴昆侖山上出，須臾化作一天雲。","py":[]},{"t":"陰長生雲：","py":[]},{"t":"夜深龍吟虎嘯時，急駕河東無暫歇。飛精運上昆侖頂，進火玉爐烹似雪。","py":[]},{"t":"張元化雲：","py":[]},{"t":"沂流一直上蓬萊，散在甘泉潤九垓。從此丹田沾潤澤，黃芽遍地一齊開。","py":[]},{"t":"原道歌雲：","py":[]},{"t":"妙運丹田須上下，須知一體合西東。幾回笑指崑山上，夾脊分明有路通。","py":[]},{"t":"玄奧集雲：","py":[]},{"t":"獨步昆侖望穹冥，龍吟虎嘯甚分明。玉池常滴陰陽髓，金帛時烹日月精。","py":[]},{"t":"羣仙珠玉雲：","py":[]},{"t":"一點丹陽事回別，須向坎中求赤血。捉來離位制陰精，配合調和有時節。","py":[]},{"t":"金丹集雲：","py":[]},{"t":"河東搬運上崑山，不動纖毫到玉關。妙在八門牢閉鎖，陰陽一氣自迴圈。","py":[]},{"t":"無一歌雲：","py":[]},{"t":"此到一複忘一可，可與元化同出沒。設若執一不能忘，大似癡貓守空窟。","py":[]},{"t":"白玉蟾雲：","py":[]},{"t":"汞心煉神赤龍性，鉛身凝氣白虎命。內外渾無一點陰，萬象光中玉清鏡。","py":[]},{"t":"純陽文集雲：","py":[]},{"t":"盜得乾坤祖，陰陽是本宗。天魂生白虎，地魄產青龍。","py":[]},{"t":"運寶泥丸住，搬精入上宮。有人明此法，萬載貌如童。","py":[]},{"t":"抱一子顯道圖雲：","py":[]},{"t":"造道原來本不難，工夫只在定中間。陰陽上下常升降，金水周流自返還。","py":[]},{"t":"紫府青龍交白虎，玄宮地軸合天關。雲收雨散神胎就，男子生兒不等閒。","py":[]},{"t":"玄奧集雲：","py":[]},{"t":"要識玄關端的處，兒女笑指最高峯。","py":[]},{"t":"最高峯，秀且奇，彼岸濛濛生紫芝。","py":[]},{"t":"只此便是長生藥，無限修行人不知。","py":[]},{"t":"許宣平玄珠歌雲：","py":[]},{"t":"天上日頭地下轉，海底蟬娟天上飛。乾坤日月本不運，皆因斗柄轉其機。","py":[]},{"t":"人心若與天心合，顛倒陰陽只片時。龍虎戰罷三田靜，拾起玄珠種在泥。","py":[]},{"t":"羣仙珠玉歌雲：","py":[]},{"t":"鉛思汞，汞思鉛，奪得乾坤造化權。性命都來兩個字，隱在丹經千萬篇。","py":[]},{"t":"卯酉周天口訣","py":[]},{"t":"周天璇璣圖","py":[]},{"t":"前段乾坤交媾，收外藥也。此段卯酉周天，收內藥也。外交媾者，後上前下，一升一降也。內交媾者，左旋右轉，一起一伏也。兩者迴圈，狀似璿璣。","py":[]},{"t":"故魏伯陽雲：循據璿璣，升降上下，周流六爻，難以察睹。世人只知有乾坤交媾，而不知卯酉周天，是猶有車而無輪，有舟而無舵，慾望遠載，其可得乎？","py":[]},{"t":"故還元篇雲：輪回玉兔與金烏，道在人身人自迷，滿目盡知調水火，到頭幾個識東西。東者，水性也。西者，金情也。一物分二，間隔東西。今得斗柄之機幹旋，則木性愛金，金情戀木，兩相交結，而金木交並矣。金本交並，方成水火全功。丹經謂之和合四象者此也。","py":[]},{"t":"故張全一鉛火祕訣雲：","py":[]},{"t":"大藥之生有時節，亥末子初正半夜。精神相媾合光華，恍恍惚惚生明月。","py":[]},{"t":"媾罷流下噴泡然，一陽來複休輕泄。急須閉在太玄關，火逼藥過尾閭穴。","py":[]},{"t":"採時用目守泥丸，垂下左上且凝歇。謂之瞻理腦升玄，右邊放下複起折。","py":[]},{"t":"六六數畢藥生乾，陽極陰生往右遷。須開關門以退火，目光下矚守坤田。","py":[]},{"t":"右上左下方凝住，三八數了一周天。此是天然真火候，自然升降自抽添。","py":[]},{"t":"也無弦望與晦朔，也無沐浴共長篇。異各剪除譬喻掃，只斯兩句是真詮。","py":[]},{"t":"其法在乾坤交媾後行之，則所結金丹不致耗散也。先以法器頂住太玄關口，次以行氣主宰下照坤臍。良久，徐徐從左上照乾頂。少停，從右降下坤臍。是為一度。又從坤臍而升上乾頂，又從乾頂而降下坤臍。如此三十六轉，是為進陽火。三十六度畢，並關以退火，亦用下照坤臍，從右上至乾頂，左邊放下坤臍，是為一度。如此二十四轉，是為退陰符。二十四度畢。","py":[]},{"t":"故張紫陽雲：","py":[]},{"t":"鬥極建四時，八節無不煩。鬥極實兀然，魁杓自移動。","py":[]},{"t":"只要兩眼皎，上下交相送。須向靜中行，莫向忙裏送。","py":[]},{"t":"所以用兩眼皎者，何也？蓋眼者，陽竅也。人之一身皆屬陰，唯有這點陽耳。我以這一點之陽，從下至上，從左至右，轉而又轉，戰退羣陰，則陽道日長，陰道日消。","py":[]},{"t":"故易曰：龍戰於野，其血玄黃。又能使真氣上下迴圈，如天河之流轉，其眼之功可謂大矣。","py":[]},{"t":"蓋人初結胎時，天一生水，先生黑睛，而有瞳仁屬腎，地二生火，而有兩皆屬心。天三生木，而有黑珠屬肝；地四生金，而有白珠屬肺；天五生土，而有上下胞胎屬脾。由此觀之，則五臟精華皆發於目也。","py":[]},{"t":"因師指竅之後，見婦人小產，半馬落胎，並抱雞之蛋，俱先生雙目而臟腑皆未成形。予始知目乃先天之靈，元神所遊之宅也。","py":[]},{"t":"皇極經世書雲：天之神，棲於日；人之神，發於目。大矣哉！人之神發於目也。生身處，此物先天地生；沒身處，此物先天地沒。水、火，木、金、上之五行，攢簇於此，肝、心、脾、肺、腎之五臟，鐘靈於此，唾、涕、精、津、氣、血、液之七物，結秀於此。其大也，天地可容，其小也，纖毫不納。茲非吾一身中之大寶也歟。","py":[]},{"t":"內指通玄訣雲：","py":[]},{"t":"含光便是生長藥，變骨成金上品仙。","py":[]},{"t":"上陽子云：","py":[]},{"t":"玄微妙訣無多吉，只在眼前人不顧。","py":[]},{"t":"崇正篇雲：","py":[]},{"t":"搬運有功連晝夜，斡旋至妙體璿璣。","py":[]},{"t":"火候歌雲：","py":[]},{"t":"欲透玄玄須謹獨，謹獨工夫機在目。","py":[]},{"t":"陳泥丸雲：","py":[]},{"t":"真陰真陽是其道，只在眼前何遠詞。","py":[]},{"t":"薛道光雲：","py":[]},{"t":"分明只在眼睛前，自是時人不見天。","py":[]},{"t":"劉海蟾雲：","py":[]},{"t":"下降上升循殼軸，左旋右複合樞機。","py":[]},{"t":"王子真雲：","py":[]},{"t":"昨宵奼女啟靈扉，窺見神仙會紫微。北斗南辰前後布，兩輪日月往來飛。","py":[]},{"t":"蕭紫虛雲：","py":[]},{"t":"如龍養珠常自顧，如雞孵卵常自抱。金液還丹在眼前，迷者多而悟者少。","py":[]},{"t":"陳翠虛雲：","py":[]},{"t":"不是燈光日月星，藥靈自有異常明。垂簾久視光明處，一顆堂堂現本真。","py":[]},{"t":"翠虛篇雲：","py":[]},{"t":"莫謂金丹事等閒，切須勤若力攢研。殷勤好與師資論，不在他途在目前。","py":[]},{"t":"玄坤集雲：","py":[]},{"t":"青牛人去幾多年，此道分明在目前。欲識目前真的處，一堂風冷月蟬娟。","py":[]},{"t":"陳泥丸雲：","py":[]},{"t":"大道分明在眼前，時人不會娛歸泉。黃芽本是乾坤氣，神水根基與汞連。","py":[]},{"t":"玄學統宗雲：","py":[]},{"t":"幾回抖搜上昆侖，運動璿璣造化分。晝夜周而還複始，嬰兒從此命常存。","py":[]},{"t":"觀吾判感歌雲：","py":[]},{"t":"這骨董，大奧妙，妙在常有觀其竅。此竅分明在目前，下士聞之即大笑。","py":[]},{"t":"金丹賦雲：","py":[]},{"t":"呼龍虎吸，魂吞魄吐。南北交媾於水火，卯酉輪還於子午。","py":[]},{"t":"總括乾坤之策，優遊變化之主。母子包羅於匡廊，育養因依於鼎釜。","py":[]},{"t":"郡仙珠玉山雲：","py":[]},{"t":"覺中覺了悟中悟，一點靈光無遮護。放開烈焰照娑婆，法界縱橫獨顯露。","py":[]},{"t":"這些消息甚幽微，木人遙指白雲歸。此個玄關口難說，目前見得便忘機。","py":[]},{"t":"南穀子云：","py":[]},{"t":"至道不遠兮，恆在目前竅。竊天地之機兮，修成仙胎。","py":[]},{"t":"純陽子云：","py":[]},{"t":"有人問我修行法，遙指天邊日月輪。","py":[]},{"t":"以上諸仙雅言，皆發明行氣主宰之義也。","py":[]},{"t":"蓋此節工夫與第四節同是一理，承上接下，端如貫珠，採取藥物於曲江之下，聚火開之而上升於乾，乾坤交媾於九宮之上，周天運之而凝結於鼎。","py":[]},{"t":"張紫陽雲：","py":[]},{"t":"都來片餉工夫，永保無窮逸樂。","py":[]},{"t":"輕清者凝於泥丸，重濁者流歸氣穴。逐日如此此抽添，如此交媾，汞漸多，鉛漸少，久則鉛將盡，汞亦幹，結成一顆摩尼，是為金液大還丹也。","py":[]},{"t":"故馬宜甫雲：","py":[]},{"t":"收得水中金，採得菩提子。運得昆侖風，長壽無生死。","py":[]},{"t":"蓋坎中之鉛，原是父之真精；離中之汞，原是母之真血。始因乾體一破，二物遂分兩弦。是以常人日離日分，分盡而死。所以至人法乾坤之體，效坎離之用，奪神功，改天命，求坎中之鉛，制離中之汞，取坎中之陽，填離中之汞。陰盡陽純，複成乾元本體。","py":[]},{"t":"故張紫陽雲：","py":[]},{"t":"取將坎位中心實，點化離官腹內陰。自此變成乾健體，潛藏飛躍盡由心。","py":[]}]},{"h":"利集·靈丹入鼎長養聖胎","paras":[{"t":"靈丹入鼎長養聖胎","py":[]},{"t":"靈丹入鼎圖","py":[]},{"t":"（內附火侯）","py":[]},{"t":"原初那點精金渾然在礦，因火所逼，遂上乾宮，漸採漸積，以烹以熔，損之又損，煉之又煉，直至煙消火滅，礦盡金純，方纔成此一粒龍虎金丹。圓陀陀，活潑潑，如露如電，非霧非煙，輝煌閃爍，光耀昆侖。放則迸開天地竅，歸兮隱人翠微宮。","py":[]},{"t":"此時藥也不生，輪也不轉，液也不降，火也不炎。五氣皆朝於上陽，三華俱聚於乾頂。陽純陰剝，丹熟珠靈。","py":[]},{"t":"紫陽翁曰：","py":[]},{"t":"羣陰剝盡丹成熟，跳出樊籠壽萬年。","py":[]},{"t":"是以唐宋屍解諸仙多於此處分路，隨意生身，出沒自由，不肯於百尺竿頭而再進一步。故有七趣之譏，落空之誚。蓋為不知重立我之性命，再造我之乾坤，變種性為佛性，化識神為元神，自造自化之妙也。","py":[]},{"t":"若命宗人不知所以自為造化，就是枯坐旁門，而道非其道也。若性宗人不知所以自為造化，就是頑空外道，而釋非其釋也。","py":[]},{"t":"此法乃仙真佛祖之所深祕，即自從金元以來而學道之人少有知之者。獨吾師尹公曰：鼎中有寶非真寶，重結靈胎是聖胎。","py":[]},{"t":"然而珠在昆侖，何由得下而結聖胎？必假神廬，竊靈陽真氣以催之。太陽真火以逼之，催逼既久，則靈丹應時脫落，吞入口中，化為金液，而直射於丹房之內，霎時雲騰雨施，電掣雷轟，鏖戰片餉之間，銷盡一身陰渣，則百靈如輻之輳殼，七寶若水之朝宗，皆聚於此矣。","py":[]},{"t":"昔無上元君謂老子曰：","py":[]},{"t":"神丹入口壽無窮也。","py":[]},{"t":"故老子修之是為道祖。","py":[]},{"t":"許宣平曰：","py":[]},{"t":"神居竅而千智生，丹入鼎而萬種化。","py":[]},{"t":"陳虛白曰：","py":[]},{"t":"我初凝結聖胎時，百脈俱停氣不馳。","py":[]},{"t":"施肩吾曰：","py":[]},{"t":"天人同一氣，彼此感而通。","py":[]},{"t":"陽自空中來，抱我主人翁。","py":[]},{"t":"然我既得靈丹入鼎矣，而內外交修，煉之而複煉之，而必至於天地合德，則太虛中自然有一點真陽以與我之靈丹合而為一。蓋吾身之靈感天地之靈，則內真外應，渾然混合。","py":[]},{"t":"金碧經雲：磁石吸鐵，隔礙潛通。大同此意。這段功夫全以至靜為主。","py":[]},{"t":"老子云：人能常清靜，天地悉皆歸。當其兩陽乍合，聖胎初凝，必須常常覺照，緊緊護持。如小龍之乍養珠，似幼女之初懷孕。牢關神室，不可使之滲漏。","py":[]},{"t":"故太白真人曰：固濟能不泄，變化在須臾。更於一切時中，四威儀內，時時照顧，念念在茲，混混沌沌，如在母胞，終日如愚而不違，不久須臾間斷也。","py":[]},{"t":"葛仙翁雲：","py":[]},{"t":"息息歸中無間斷，天真胎裏自凝堅。","py":[]},{"t":"張用成雲：","py":[]},{"t":"一粒靈丹吞入腹，始知我命不由天。","py":[]},{"t":"石得之雲：","py":[]},{"t":"將來掌上霞光燦，吞入腹中宮殿新。","py":[]},{"t":"趙緣督雲：","py":[]},{"t":"神丹飛落黃金室，嬰兒降生極樂國。","py":[]},{"t":"呂純陽雲：","py":[]},{"t":"刀主餌了丹書降，跳出塵籠上九天。","py":[]},{"t":"朱文公雲：","py":[]},{"t":"刀圭一入口，白日生羽翰。","py":[]},{"t":"李清庵雲：","py":[]},{"t":"一顆寶珠吞入腹，作個全真仙眷屬。","py":[]},{"t":"陳希夷雲：","py":[]},{"t":"邈無蹤跡歸丹房，潛有機關結聖胎。","py":[]},{"t":"薛紫賢雲：","py":[]},{"t":"四象包含歸戊己，辛勤十月產嬰孩。","py":[]},{"t":"悟真篇雲：","py":[]},{"t":"果生枝上終期熟，子在胞中豈有殊。","py":[]},{"t":"醉中吟雲：","py":[]},{"t":"寶珠笑舞辭天穀，才脫胞胎又入胎。","py":[]},{"t":"張紫陽雲：","py":[]},{"t":"嬰兒是一含真炁，十月胎圓入聖基。","py":[]},{"t":"呂純陽雲：","py":[]},{"t":"天生一物變三才，交感陰陽結聖胎。","py":[]},{"t":"白玉蟾雲：","py":[]},{"t":"雞能抱卵心常聽，蟬到成形殼始分。","py":[]},{"t":"俞石澗雲：","py":[]},{"t":"虎嘯一聲龍出窟，鸞飛鳳舞入金城。","py":[]},{"t":"羣仙珠玉雲：","py":[]},{"t":"一粒餐兮天地壽，死生生死不相干。","py":[]},{"t":"張紫陽雲：","py":[]},{"t":"相吞相咽卻相親，始覺男兒有孕身。","py":[]},{"t":"鐘離翁雲：","py":[]},{"t":"胎內嬰兒就，勤加溫養功。時時照丹房，刻刻守黃中。","py":[]},{"t":"陳泥丸雲：","py":[]},{"t":"男兒懷孕是胎仙，只為蟾光夜夜圓。奪得天機真造化，身中自有玉清天。","py":[]},{"t":"陳抱一雲：","py":[]},{"t":"大道無私感即來，神仙此語豈虛哉。苟非著意求鉛汞，爭悟天機結聖胎。","py":[]},{"t":"玄奧集雲：","py":[]},{"t":"閬苑蟠桃自熟時，摘來服餌莫教遲。幾回下手潛偷處，無限神仙總不知。","py":[]},{"t":"龍眉子云：","py":[]},{"t":"形如雀卵團團大，間似驪珠珠珠圓。龍子脫胎吞入口，此身已證陸行仙。","py":[]},{"t":"紫虛真人云：","py":[]},{"t":"初煉還丹須入室，婦人懷孕更無殊。聖胎凝結圓成後，出入行藏豈有拘。","py":[]},{"t":"白紫清雲：","py":[]},{"t":"和將戊己作丹妒，煉得紅丸化玉酥。慢守火符三百日，產成一顆夜明珠。","py":[]},{"t":"張真人贈白龍洞主歌雲：","py":[]},{"t":"從此根苗漸長成，隨時灌溉抱真精。十月脫胎存入口，不覺凡身已有靈。","py":[]},{"t":"白玉蟾雲：","py":[]},{"t":"怪事教人笑幾回，男兒今也會懷胎。自家精血自交媾，身裏夫妻是妙哉。","py":[]},{"t":"黃元吉雲：","py":[]},{"t":"鼎內金丹燦爛光，無由摘爾到黃房。忽然夜半天風便，吹送靈兒歸故鄉。","py":[]},{"t":"陳翠虛雲：","py":[]},{"t":"道要無中養就兒，個中別有真端的。都緣簡易妙天機，散在丹書不肯泄。","py":[]},{"t":"王重陽雲：","py":[]},{"t":"閑中偶爾到天臺。忽見霞光五色開。想是金丹初變化，取歸鼎內結嬰孩。","py":[]},{"t":"上陽子云：","py":[]},{"t":"玉皇若也問丹材，偃月爐中取下來。馳騁英雄吞一粒，男兒懷了一年胎。","py":[]},{"t":"陳致虛雲：","py":[]},{"t":"饑餐渴飲困來眠，一道分明體自然。十月聖胎完就了，一聲霹靂出丹山。","py":[]},{"t":"至於釋教教人亦不外此。如楞嚴經曰：行如佛同受佛氣，分如中陰身自求。父母陰信冥通入，如來種名生貴住。既遊道胎，親奉覺乳，如胎已成人相。不缺名方，便具足住。容貌如佛，心相亦同。名正心住，身心合成，日益增長，名不退住，十身靈相，一時具足，名童真住。形成出胎，親為佛子，名法王子住。表以成人，如國大王，以諸國事分委太子，彼剎利王。世子長成，陳列灌頂，名灌頂住。夫入如來種者，以種性而為如來之種子，以自造化如來也。故曰道胎，又曰覺乳，其與婦人之乳兒，玄門之胎仙，亦何以異？及至形成出貽，親為佛子，豈不是真人出現，大神通從此，天仙可相賀耶？","py":[]},{"t":"蓋丹書梵典，皆有次序口訣，但人不知。而驀直看過去了正，是珠在路旁人不拾。惜哉！予今略摘此數條表而出之，以引古之是而證今之非也。","py":[]},{"t":"火候","py":[]},{"t":"火候崇正圖","py":[]},{"t":"火候最祕，聖人不傳，令則露之。藥非火不產，藥熟則火化矣。火非藥不生，火到則丹成矣。且火候之奧，非可一概而論。","py":[]},{"t":"故未得丹時，須借武火以凝之，既得丹時，須藉文火以養之。文火者。結實之火也。其養之法，節其寒溫消息是也。","py":[]},{"t":"故參同契曰：候視加謹慎，審察辨寒溫。審其火之未燃也，須藉巽風以吹之。察其火之既燃也，須資神水以活之。若太過，則損之；若不及，則益之，俾得中和而無火燥、火寒之病矣。","py":[]},{"t":"蓋火之寒燥，全在意念上發端。","py":[]},{"t":"陳虛白曰：念不可起，念起則火燥；意不可散，意散則火冷。唯只要一念不起，一意不散，含光默然，真息綿綿，圓明覺照，常自惺惺，此長養聖胎之真火候也。","py":[]},{"t":"故白玉蟾曰：","py":[]},{"t":"採藥物於不動之中，行火候於無為之內。","py":[]},{"t":"張三峯曰：","py":[]},{"t":"以默以柔存火性，勿忘勿助養靈胎。","py":[]},{"t":"劉海蟾曰：","py":[]},{"t":"兀兀無為融至寶，微微文文養潛龍。","py":[]},{"t":"張紫陽曰：","py":[]},{"t":"自有天然真火育，不須柴炭及吹噓。","py":[]},{"t":"又曰：","py":[]},{"t":"謾守藥爐著火候，但安神息任天然。","py":[]},{"t":"此四翁乃列仙中之錚錚者，皆以天然真火、自然妙用而成無上至真之道。又何嘗用卦爻斤兩，年月日時哉？","py":[]},{"t":"今時之人，錯會仙師本意，泥象執文，認指為月，而必欲推算卦體之策數，求合卦書之陰陽。吾恐終身役役，而不見其成功，倏然疲斃，而不知其歸處。","py":[]},{"t":"豈不見張平敘雲：","py":[]},{"t":"此中得意須忘象，若究羣爻謾役情。","py":[]},{"t":"高象先雲：","py":[]},{"t":"晝夜屯蒙法自然，焉用孜孜看火侯。","py":[]},{"t":"陳沖素雲：","py":[]},{"t":"火雖有侯不須時，些子機關我自知。","py":[]},{"t":"彭真一雲：","py":[]},{"t":"從來真火無形象，不得師傳亦大難。","py":[]},{"t":"蕭子虛雲：","py":[]},{"t":"藥物調和，悟者甚易。火候消息，行之恐難。","py":[]},{"t":"一十月功夫存杳杳綿綿之息，三萬年氣數在來來往往之間。所以養丹田之寶，此寶常在在丹鼎之珠。此珠複還，駕動河車。離塵世尾閭之海，移居天穀上昆侖蓬島之山。前數句謂成丹之時脫胎而入日，末一句謂功成之後脫胎而出殼，中間兩句謂溫養子珠，長養聖胎。","py":[]},{"t":"張三峯曰：","py":[]},{"t":"年月日時空有著，卦爻斤兩亦支離。若存會得綿綿意，正是勿忘勿助時。","py":[]},{"t":"白紫清曰：流俗淺識。未學凡夫豈知元始天尊與天仙地仙，日日採藥物而不停，藥物愈採而無窮也。又豈知山河大地與蠢動含靈，時時行火候而無暫助，火候愈行而不歇也。神凝則精氣聚而百寶結者，結胎之藥物也。真息往來而未嘗少有間斷者，溫養之火候也。","py":[]},{"t":"陳虛白曰：火候之要，尤當以真息求之。","py":[]},{"t":"丘長春曰：一念不離方寸是真空。此養胎之真火也。夫真火者，我之神也，而與天地之神、虛空之神同其神也。真候者，我之息也，而與天地之息、虛空之息同其息也。","py":[]},{"t":"左元放曰：","py":[]},{"t":"火候無為合自然，自然真火養胎仙。但存神息居丹扃，調變先天接後天。","py":[]},{"t":"王重陽曰：","py":[]},{"t":"聖胎既凝，養以文火。安神定息，任其自如。","py":[]},{"t":"此以神感，彼以神應。天機妙用，自然而然。","py":[]},{"t":"予於是而知神息者，火候也。而孟子之所謂勿忘勿助、老氏之所謂綿綿若存、釋氏之所謂不得勤不得怠者，是皆神息之自然火候之微旨也。","py":[]},{"t":"故曰：","py":[]},{"t":"神仙不肯分明說，說得分明笑殺人。","py":[]},{"t":"長養聖胎圖","py":[]}]}],"py":[]};